window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["protein"]={"id": "protein", "title": "蛋白质代谢", "sub": "第八章 · 55页教材逐图讲解 · 20道考题", "sub2": "氨基酸代谢 · 尿素循环 · 一碳单位 · 蛋白质合成", "modules": [{"i": 0, "name": "模块一：蛋白质的降解", "slides": [{"i": 0, "sec": "蛋白质代谢", "title": "蛋白质代谢总览 (p1)", "notes": "标题页：蛋白质分解和氨基酸代谢。\u000b氨基酸代谢库连接食物蛋白、组织蛋白和非蛋白含N物。\u000b三条去路：脱羧→胺类；\u000b脱氨→α-酮酸+NH3；\u000b合成非蛋白含N物。", "page": 1, "level": "掌握", "img": "assets/img/protein/p001.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "蛋白质代谢", "title": "氨基酸代谢库全图 (p2)", "notes": "完整展示体内氨基酸代谢库全景：食物蛋白→消化→血液aa⇌组织aa。\u000b标注三条去路和每种产物的代谢终点。\u000b本章所有后续内容都是这幅图的展开。", "page": 2, "level": "掌握", "img": "assets/img/protein/p002.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "蛋白质代谢", "title": "蛋白质酶促降解 (p3)", "notes": "蛋白质在蛋白水解酶作用下肽键断裂→氨基酸。\u000b分内肽酶(水解内部肽键)和外肽酶(C端/N端逐个切)。\u000b不同酶有不同的肽键专一性——胰蛋白酶切Lys/Arg羧基端。", "page": 3, "level": "掌握", "img": "assets/img/protein/p003.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "蛋白质代谢", "title": "蛋白质酶促降解示意 (p4)", "notes": "图中以图示展示蛋白水解酶的分类和作用位点：内肽酶从内部切断肽链→多肽；\u000b外肽酶从末端逐个切下aa→游离aa。\u000b两种酶协同完成蛋白质的彻底降解。", "page": 4, "level": "掌握", "img": "assets/img/protein/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "蛋白质代谢", "title": "外源蛋白消化吸收 (p5)", "notes": "完整消化流程：胃蛋白酶(胃)→多肽+少量aa→胰蛋白酶等(小肠)→短肽+游离aa→外肽酶→二肽→二肽酶→游离aa→吸收。\u000b逐级水解的级联过程。", "page": 5, "level": "理解", "img": "assets/img/protein/p005.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "蛋白质代谢", "title": "消化系统组织结构 (p6)", "notes": "三个关键组织：胃腺(壁细胞HCl+主细胞胃蛋白酶原)；\u000b胰腺外分泌细胞(酶原→活性酶)；\u000b小肠绒毛(吸收aa)。\u000b酶原→活性酶的激活是消化酶调控的关键。", "page": 6, "level": "了解", "img": "assets/img/protein/p006.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "蛋白质代谢", "title": "组织蛋白降解 (p7)", "notes": "胞内蛋白降解两条途径：①溶酶体途径——组织蛋白酶，无选择降解；\u000b②泛素-蛋白酶体——泛素(76aa)标记→K48链→26S蛋白酶体选择性降解(需ATP)。\u000b泛素C端Gly与靶蛋白Lys形成异肽键。", "page": 7, "level": "掌握", "img": "assets/img/protein/p007.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "蛋白质代谢", "title": "泛素结构 (p8)", "notes": "泛素三维结构：76aa，紧凑球状，C端柔性突出。\u000b7个Lys(K6/11/27/29/33/48/63)——每个可形成泛素链。\u000bK48链→降解信号；\u000bK63链→信号转导/DNA修复。", "page": 8, "level": "理解", "img": "assets/img/protein/p008.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "蛋白质代谢", "title": "泛素化修饰类型 (p9)", "notes": "三种泛素化：①单泛素化→内吞/组蛋白调控；\u000b②多泛素化→信号转导/DNA修复；\u000b③多聚泛素化(K48链→降解，K63链→信号转导)。\u000b多聚泛素化：泛素C端Gly与上一个泛素K48/K63形成异肽键。", "page": 9, "level": "理解", "img": "assets/img/protein/p009.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 9, "sec": "蛋白质代谢", "title": "泛素-蛋白酶体降解 (p10)", "notes": "E1(泛素活化酶,ATP)→E2(泛素结合酶)→E3(泛素连接酶)转移泛素至靶蛋白Lys。\u000b多轮→K48多聚泛素链。\u000b26S蛋白酶体识别→去折叠→去泛素→降解为短肽。\u000b图中完整标注E1/E2/E3和蛋白酶体。", "page": 10, "level": "掌握", "img": "assets/img/protein/p010.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "蛋白质代谢", "title": "泛素介导降解示意 (p11)", "notes": "简洁总结：泛素标记→蛋白酶体识别→去泛素→降解。\u000b泛素可回收(去泛素化酶DUBs)。\u000b真核生物约80-90%胞内蛋白经此途径降解——最主要的蛋白质质量控制机制。", "page": 11, "level": "了解", "img": "assets/img/protein/p011.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "蛋白质代谢", "title": "植物微生物蛋白质水解 (p12)", "notes": "植物：种子/幼芽含活性蛋白酶，萌发时水解贮藏蛋白。\u000b微生物：枯草杆菌分泌蛋白酶至培养基→水解蛋白→吸收aa。\u000b豆科种子含丰富蛋白酶抑制剂(生食不易消化)。", "page": 12, "level": "了解", "img": "assets/img/protein/p012.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "蛋白质代谢", "title": "氨基酸分解代谢总览 (p13)", "notes": "第二节开始：脱氨基是aa分解第一步——三种方式：转氨基、氧化脱氨基、联合脱氨基。\u000b产物α-酮酸→碳代谢，NH3→氮代谢(尿素循环)。\u000b图中用箭头标注三种脱氨方式的关系。", "page": 13, "level": "掌握", "img": "assets/img/protein/p013.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "蛋白质代谢", "title": "脱氨基方式总览 (p14)", "notes": "图中总结三种脱氨基方式：转氨基(转移NH2)、氧化脱氨基(释放NH3)、联合脱氨基(转氨+氧化脱氨结合)。\u000b三者逐步递进——从收集NH2到集中释放NH3。", "page": 14, "level": "掌握", "img": "assets/img/protein/p014.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "protein_mcq_1", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】泛素-蛋白酶体途径中E1/E2/E3的功能？", "o": ["A. E1活化泛素,E2传递,E3连接靶蛋白", "B. E1/E2/E3均为蛋白酶体催化亚基", "C. E1降解蛋白,E2标记,E3激活泛素", "D. E1连接靶蛋白,E2传递,E3活化泛素"], "a": "A", "e": "E1(泛素活化酶,消耗ATP)→E2(泛素结合酶)→E3(泛素连接酶)识别靶蛋白→泛素C端Gly与靶蛋白Lys ε-NH2形成异肽键。", "kp": "protein_s0_9"}, {"id": "protein_mcq_2", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】ALT/GPT催化的反应？", "o": ["A. Asp+α-KG↔OAA+Glu,需PLP为辅酶", "B. Ala+α-KG↔丙酮酸+Glu,肝脏活力最高", "C. Glu+NAD+→α-KG+NH3,线粒体酶", "D. Ala+OAA↔丙酮酸+Asp,胞质酶"], "a": "D", "e": "ALT(谷丙转氨酶):Ala+α-KG→丙酮酸+Glu(肝脏活力最高)。AST(谷草转氨酶):Asp+α-KG→OAA+Glu。辅酶都是PLP(VB6)。", "kp": null}, {"id": "protein_mcq_3", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】Glu脱氢酶的特征？", "o": ["A. 线粒体酶,脱氨活力最强,受ATP/GTP抑制", "B. 胞质酶,以FAD为辅基,氧化脱氨", "C. 仅存于肝脏,不需辅酶,直接脱氨", "D. 内质网酶,以NAD+为辅酶,还原氨化"], "a": "A", "e": "Glu脱氢酶是线粒体酶,催化Glu+NAD(P)++H2O→α-KG+NH3+NAD(P)H。ATP/GTP/NADH抑制;ADP/NAD+激活。", "kp": "protein_s0_3"}, {"id": "protein_mcq_4", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【理解】嘌呤核苷酸循环主要存在于哪个组织？", "o": ["A. 肝脏,以Glu脱氢酶为中心联合脱氨", "B. 脑组织,以Gln合成酶为主解氨毒", "C. 骨骼肌,Glu脱氢酶活力低需此途径", "D. 肾脏,以Gln酶释放NH3调节酸碱"], "a": "D", "e": "骨骼肌Glu脱氢酶活力低→以嘌呤核苷酸循环为主要脱氨方式。涉及Asp/IMP/腺苷酸代琥珀酸/AMP/腺苷酸脱氨酶。", "kp": "protein_s0_5"}, {"id": "protein_mcq_5", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】转氨酶的辅酶是？", "o": ["A. 磷酸吡哆醛(PLP),VB6衍生物", "B. 黄素腺嘌呤二核苷酸(FAD)", "C. 烟酰胺腺嘌呤二核苷酸(NAD+)", "D. 焦磷酸硫胺素(TPP),VB1衍生物"], "a": "A", "e": "PLP(磷酸吡哆醛)是所有转氨酶的辅酶(VB6衍生物)。PLP与酶Lys形成Schiff碱→转移NH2给α-酮酸。", "kp": "protein_s0_3"}, {"id": "protein_mcq_6", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】尿素循环的限速酶是？", "o": ["A. 精氨酸酶,水解精氨酸产生尿素", "B. 氨甲酰磷酸合成酶I(CPS-I),需NAG激活", "C. 鸟氨酸转氨甲酰酶(OTC),线粒体酶", "D. 精氨琥珀酸合成酶(ASS),细胞质酶"], "a": "D", "e": "CPS-I:NH3+CO2+2ATP→氨甲酰磷酸+2ADP+Pi。需Mg2+和N-乙酰谷氨酸(NAG)别构激活。是尿素循环限速步骤。", "kp": "protein_s0_12"}, {"id": "protein_mcq_7", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】每合成1分子尿素消耗几个高能磷酸键？", "o": ["A. 2个,来自2ATP→2ADP+2Pi", "B. 4个,2ATP+1ATP→AMP+PPi≈4个高能键", "C. 3个,来自3ATP→3ADP+3Pi", "D. 1个,来自1ATP→ADP+Pi"], "a": "A", "e": "2ATP(氨甲酰磷酸合成→2ADP)+1ATP→AMP+PPi(精氨琥珀酸合成,≈2个高能键)=4个高能磷酸键。", "kp": "protein_s0_0"}, {"id": "protein_mcq_8", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】尿素的两个氮原子分别来自？", "o": ["A. NH3(氨甲酰磷酸)和Asp(精氨琥珀酸)", "B. 均来自游离NH3,经CPS-I催化", "C. Gln的酰胺N和游离NH3", "D. 尿酸分解产生的N和NH3"], "a": "A", "e": "第1个N:NH3+HCO3-→氨甲酰磷酸(CPS-I)。第2个N:Asp+瓜氨酸→精氨琥珀酸(ASS)。CPS-I在线粒体,ASS在细胞质。", "kp": "protein_s0_12"}, {"id": "protein_mcq_9", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】氨在血液中主要运输形式是？", "o": ["A. 尿素,由肝脏合成后经血液运至肾", "B. 尿酸,嘌呤代谢终产物,溶解度低", "C. 谷氨酰胺(Gln),中性无毒自由过膜", "D. NH4Cl,以离子形式随血液运输"], "a": "C", "e": "Gln是中性无毒分子→Gln合成酶:Glu+NH3+ATP→Gln+ADP+Pi。脑组织依赖Gln合成酶解氨毒。肝Gln酶→Glu+NH3→尿素。", "kp": "protein_s0_1"}, {"id": "protein_mcq_10", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】葡萄糖-丙氨酸循环的意义？", "o": ["A. 仅将血液葡萄糖运至肌肉供能", "B. 运NH3(Ala至肝)+回收碳骨架(糖异生)", "C. 仅将丙氨酸运至肝脏降解供能", "D. 运输乳酸至肝脏进行Cori循环"], "a": "B", "e": "一举两得:运走NH3(Ala携带-NH2到肝);运走丙酮酸(避免乳酸积累)→肝糖异生→葡萄糖→肌肉。", "kp": "protein_s0_12"}], "judge": [], "fill": [{"id": "protein_fill_1", "modI": 0, "q": "泛素C末端Gly76的α-COOH与靶蛋白Lys残基的________形成________键,这是泛素化修饰的标志。", "a": "泛素C末端Gly76的α-COOH与靶蛋白Lys残基的________形成________键,这是泛素化修饰的标志。", "kp": "protein_s0_8"}], "short": [{"id": "protein_short_1", "modI": 0, "q": "简述泛素-蛋白酶体途径降解蛋白质的主要步骤。", "a": "简述泛素-蛋白酶体途径降解蛋白质的主要步骤。", "kp": "protein_s0_9"}], "calc": [{"id": "protein_calc_3", "modI": 0, "q": "某蛋白质含100个氨基酸残基,经泛素-蛋白酶体途径降解。问:(1)形成K48多聚泛素链至少需要几个泛素分子? (2)降解过程消耗多少ATP?", "a": "某蛋白质含100个氨基酸残基,经泛素-蛋白酶体途径降解。问:(1)形成K48多聚泛素链至少需要几个泛素分子? (2)降解过程消耗多少ATP?", "steps": "某蛋白质含100个氨基酸残基,经泛素-蛋白酶体途径降解。问:(1)形成K48多聚泛素链至少需要几个泛素分子? (2)降解过程消耗多少ATP?", "kp": "protein_s0_9"}], "term": [{"id": "protein_term_1", "modI": 0, "term": "请解释：泛素-蛋白酶体途径", "def": "名词：泛素-蛋白酶体途径", "kps": "", "kp": "protein_s0_9"}]}, {"i": 1, "name": "模块二：氨基酸脱氨基", "slides": [{"i": 0, "sec": "蛋白质代谢", "title": "转氨基作用定义 (p15)", "notes": "α-AA+α-酮酸↔α-酮酸+α-AA。\u000b在转氨酶作用下，氨基转移——原来的氨基酸变为酮酸，原来的酮酸变为氨基酸。\u000b反应可逆——是aa分解和合成的交汇点。\u000b辅酶：磷酸吡哆醛(PLP,VB6)。", "page": 15, "level": "掌握", "img": "assets/img/protein/p015.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "蛋白质代谢", "title": "转氨酶特征 (p16)", "notes": "①存在于线粒体和胞液中；\u000b②绝大多数以α-酮戊二酸为-NH2受体(少数以OAA为受体)；\u000b③辅酶PLP——形成Schiff碱→转移NH2给α-KG→生成Glu。\u000b转氨酶不释放游离NH3——只转移NH2。", "page": 16, "level": "掌握", "img": "assets/img/protein/p016.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "蛋白质代谢", "title": "ALT与AST (p17)", "notes": "ALT(GPT)：Ala+α-KG→丙酮酸+Glu(肝活力最高)。\u000bAST(GOT)：Asp+α-KG→OAA+Glu。\u000b胞液转氨酶收集-NH2→集中在Glu。\u000b血清ALT/AST↑→肝细胞损伤(ALT更特异)。", "page": 17, "level": "掌握", "img": "assets/img/protein/p017.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "蛋白质代谢", "title": "氧化脱氨基定义 (p18)", "notes": "α-AA在氧化酶作用下→α-亚氨基酸→H2O自发水解→α-酮酸+NH3。\u000bL-AA氧化酶(黄素酶,FAD/FMN)；\u000bD-AA氧化酶(FAD)。\u000b最重要的是L-Glu脱氢酶——脱氨活力最强的酶。", "page": 18, "level": "掌握", "img": "assets/img/protein/p018.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "蛋白质代谢", "title": "L-Glu脱氢酶 (p19)", "notes": "线粒体酶，脱氨活力最强。\u000bGlu+NAD(P)++H2O→α-KG+NH4++NAD(P)H。\u000b别构调节：ATP/GTP/NADH抑制(高能荷→减少脱氨)；\u000bADP/NAD+激活(低能荷→加强脱氨)。\u000b连接aa代谢与TCA的关键酶。", "page": 19, "level": "掌握", "img": "assets/img/protein/p019.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "蛋白质代谢", "title": "联合脱氨基 (p20)", "notes": "定义：转氨基+氧化脱氨基(或嘌呤核苷酸循环)配合。\u000b机制：①转氨酶将各种aa的-NH2→Glu；\u000b②Glu脱氢酶→α-KG+NH3；\u000b③α-KG再生。\u000b肝脏以此为主要脱氨方式。", "page": 20, "level": "掌握", "img": "assets/img/protein/p020.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "蛋白质代谢", "title": "嘌呤核苷酸循环 (p21)", "notes": "骨骼肌的主要脱氨方式(Glu脱氢酶活力低)。\u000b①转氨：aa+α-KG→α-酮酸+Glu；\u000b②AST：Glu+OAA→α-KG+Asp；\u000b③Asp+IMP+GTP→腺苷酸代琥珀酸。\u000b图中标注每一步。", "page": 21, "level": "理解", "img": "assets/img/protein/p021.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "蛋白质代谢", "title": "嘌呤核苷酸循环-后续 (p22)", "notes": "④腺苷酸代琥珀酸裂解→AMP+延胡索酸；\u000b⑤AMP脱氨酶→IMP+NH3释放。\u000bIMP循环再生。\u000b净效果：aa的NH2→NH3，Asp和IMP循环使用。\u000b图中完整标注酶和ATP/GTP消耗。", "page": 22, "level": "理解", "img": "assets/img/protein/p022.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "蛋白质代谢", "title": "脱氨基小结 (p23)", "notes": "aa分解始于转氨基→联合脱氨基脱去-NH2。\u000b产物α-酮酸→TCA/糖异生/氧化供能；\u000bNH3→尿素循环解毒。\u000b肝以Glu脱氢酶为中心，骨骼肌以嘌呤核苷酸循环为主。", "page": 23, "level": "理解", "img": "assets/img/protein/p023.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 9, "sec": "蛋白质代谢", "title": "脱羧基作用 (p24)", "notes": "α-AA在脱羧酶作用下→伯胺+CO2。\u000b专一性极高——一种AA一种脱羧酶。\u000b辅酶PLP(His脱羧酶除外)。\u000b反应不可逆。\u000b产物胺类有重要生理活性。", "page": 24, "level": "理解", "img": "assets/img/protein/p024.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "蛋白质代谢", "title": "脱羧产物实例 (p25)", "notes": "①Glu→GABA(抑制性神经递质)；\u000b②Cys→牛磺酸(促脂类消化)；\u000b③Asp→β-丙氨酸(泛酸成分)；\u000b④His→组胺(降血压/过敏)；\u000b⑤Tyr→酪胺(升血压)。\u000b胺类是aa代谢的高附加值产物。", "page": 25, "level": "理解", "img": "assets/img/protein/p025.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "蛋白质代谢", "title": "脱羧基作用小结 (p26)", "notes": "①脱羧不是aa代谢主要途径；\u000b②胺类有重要生理作用(神经递质/激素等)。\u000b胺氧化酶(Cu2+)→醛→酸→排出。\u000b组胺过量→过敏(抗组胺药)；\u000bGABA不足→癫痫；\u000b5-HT不足→抑郁。", "page": 26, "level": "了解", "img": "assets/img/protein/p026.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "蛋白质代谢", "title": "NH3排氨方式 (p27)", "notes": "三种排氨方式：排NH3动物(水生——扩散入水)；\u000b排尿酸动物(鸟类/爬行类——尿酸不溶省水)；\u000b排尿素动物(哺乳类——尿素可溶需少量水)。\u000b进化中适应水环境的代谢策略。", "page": 27, "level": "理解", "img": "assets/img/protein/p027.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "蛋白质代谢", "title": "氨的运输 (p28)", "notes": "NH3剧毒→必须以Gln形式运输。\u000bGln合成酶：Glu+NH3+ATP→Gln+ADP+Pi。\u000bGln是中性无毒分子→血液→肝脏Gln酶→Glu+NH3→尿素循环。\u000b脑组织尤赖Gln合成酶解氨毒。", "page": 28, "level": "掌握", "img": "assets/img/protein/p028.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "protein_mcq_11", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】以下哪个是纯生酮氨基酸？", "o": ["A. Ala,碳骨架→丙酮酸,可糖异生", "B. Glu,碳骨架→α-KG,进入TCA", "C. Leu,碳骨架→乙酰CoA+乙酰乙酸", "D. Phe,碳骨架→延胡索酸+乙酰乙酸"], "a": "D", "e": "纯生酮只有Leu和Lys。Leu→乙酰CoA+乙酰乙酸;Lys→乙酰乙酰CoA。Phe/Tyr/Trp/Ile/Thr是生糖兼生酮。", "kp": "protein_s1_0"}, {"id": "protein_mcq_12", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】脱羧基作用产物GABA由哪个氨基酸生成？", "o": ["A. Asp脱羧→β-丙氨酸,泛酸前体", "B. His脱羧→组胺,过敏反应介质", "C. Tyr脱羧→酪胺,升高血压", "D. Glu脱羧→γ-氨基丁酸,抑制性递质"], "a": "D", "e": "Glu脱羧酶(GAD,PLP辅酶)→GABA。GABA是CNS最重要的抑制性神经递质。GAD仅存在于GABA能神经元中。", "kp": "protein_s1_11"}, {"id": "protein_mcq_13", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【了解】苯丙酮尿症(PKU)缺陷酶？", "o": ["A. 酪氨酸酶,催化Tyr→多巴→黑色素", "B. 苯丙氨酸羟化酶(PAH),Phe→Tyr受阻", "C. 转氨酶,催化Phe→苯丙酮酸", "D. 脱羧酶,催化Phe→苯乙胺"], "a": "A", "e": "PAH缺陷→Phe→Tyr受阻→Phe积累→苯丙酮酸(尿中检出)→智力障碍。新生儿筛查→低Phe饮食。", "kp": "protein_s1_2"}, {"id": "protein_mcq_14", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】多聚泛素化K48和K63的功能区别？", "o": ["A. 两者功能完全相同,均标记降解", "B. K48链→蛋白降解;K63链→信号转导", "C. K48链→DNA修复;K63链→蛋白降解", "D. 两者均无特定生物学功能"], "a": "C", "e": "K48连接链(>=4个泛素)→26S蛋白酶体识别→降解。K63连接链→信号转导(NF-κB)/DNA修复/内吞。", "kp": null}, {"id": "protein_mcq_15", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【了解】白化病的缺陷酶？", "o": ["A. 苯丙氨酸羟化酶(PAH),Phe→Tyr", "B. 转氨酶(ALT/AST),催化转氨反应", "C. 脱羧酶(PLP辅酶),催化脱羧反应", "D. 酪氨酸酶(含Cu2+),Tyr→多巴→黑色素"], "a": "D", "e": "酪氨酸酶(含Cu2+)→Tyr→多巴→多巴醌→黑色素。酶缺陷→无黑色素→白化。OCA1最常见。", "kp": null}, {"id": "protein_mcq_16", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】联合脱氨基的α-KG作用？", "o": ["A. 作为底物被不可逆消耗掉", "B. 循环使用:接受NH2→Glu→脱氨再生", "C. 直接释放NH3排入血液", "D. 储存NH3形成谷氨酰胺(Gln)"], "a": "A", "e": "α-KG在联合脱氨中循环:转氨酶→接受aa的NH2→Glu;Glu脱氢酶→脱氨→再生α-KG+NH3。NH2的搬运工。", "kp": "protein_s1_5"}, {"id": "protein_mcq_17", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】泛素C端Gly与靶蛋白形成什么键？", "o": ["A. 靶蛋白Glu的γ-COOH形成酯键", "B. 靶蛋白Lys的ε-NH2形成异肽键", "C. 靶蛋白Ser的-OH形成醚键", "D. 靶蛋白Cys的-SH形成硫酯键"], "a": "B", "e": "泛素C末端Gly76的α-COOH与靶蛋白Lys残基的ε-NH2形成异肽键——泛素化修饰的标志性化学键。", "kp": "protein_s1_4"}, {"id": "protein_mcq_18", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】酶原激活的生物学意义？", "o": ["A. 加快酶促反应速率,提高催化效率", "B. 防止消化酶在合成部位水解自身组织", "C. 无特殊生物学意义,是进化残留", "D. 改变酶的底物专一性和最适pH"], "a": "B", "e": "胃蛋白酶原→胃蛋白酶需HCl;胰蛋白酶原→胰蛋白酶需肠激酶。酶原形式=空间隔离+需激活=自我保护。", "kp": "protein_s1_4"}, {"id": "protein_mcq_19", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】氨甲酰磷酸合成酶I(CPS-I)的别构激活剂是？", "o": ["A. 柠檬酸,来自TCA循环的中间物", "B. ATP,提供磷酸基团和反应能量", "C. NAG(N-乙酰谷氨酸),由Arg激活合成", "D. GTP,提供别构调节所需的能量"], "a": "D", "e": "CPS-I是尿素循环限速酶,需NAG别构激活。NAG由NAG合酶以乙酰CoA+Glu合成——Arg激活NAG合酶。", "kp": "protein_s1_0"}, {"id": "protein_mcq_20", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【理解】生糖氨基酸与生酮氨基酸的根本区别？", "o": ["A. 碳原子数量不同,糖aa碳数更少", "B. 碳骨架能否转化为TCA中间物(能=生糖)", "C. 分子量大小不同,生糖aa分子更小", "D. 含氮量高低不同,生酮aa含氮更多"], "a": "A", "e": "生糖aa碳骨架→丙酮酸/OAA/α-KG等→TCA→糖异生→葡萄糖。生酮aa碳骨架→乙酰CoA→不能→糖(丙酮酸脱氢酶不可逆)。", "kp": "protein_s1_0"}], "judge": [], "fill": [{"id": "protein_fill_5", "modI": 1, "q": "转氨酶的辅酶是________,它是维生素________的衍生物。", "a": "转氨酶的辅酶是________,它是维生素________的衍生物。", "kp": "protein_s1_1"}], "short": [{"id": "protein_short_4", "modI": 1, "q": "简述葡萄糖-丙氨酸循环及其生理意义。", "a": "简述葡萄糖-丙氨酸循环及其生理意义。", "kp": "protein_s1_7"}, {"id": "protein_short_5", "modI": 1, "q": "简述联合脱氨基作用的两种方式。", "a": "简述联合脱氨基作用的两种方式。", "kp": "protein_s1_5"}], "calc": [{"id": "protein_calc_4", "modI": 1, "q": "计算1分子谷氨酸(Glu)经联合脱氨基作用后,碳骨架进入TCA彻底氧化净产ATP数(不计NH3处理)。", "a": "计算1分子谷氨酸(Glu)经联合脱氨基作用后,碳骨架进入TCA彻底氧化净产ATP数(不计NH3处理)。", "steps": "计算1分子谷氨酸(Glu)经联合脱氨基作用后,碳骨架进入TCA彻底氧化净产ATP数(不计NH3处理)。", "kp": "protein_s1_5"}], "term": [{"id": "protein_term_2", "modI": 1, "term": "请解释：联合脱氨基作用", "def": "名词：联合脱氨基作用", "kps": "", "kp": "protein_s1_5"}, {"id": "protein_term_4", "modI": 1, "term": "请解释：转氨基作用", "def": "名词：转氨基作用", "kps": "", "kp": "protein_s1_0"}, {"id": "protein_term_6", "modI": 1, "term": "请解释：嘌呤核苷酸循环", "def": "名词：嘌呤核苷酸循环", "kps": "", "kp": "protein_s1_7"}, {"id": "protein_term_12", "modI": 1, "term": "请解释：氧化脱氨基作用", "def": "名词：氧化脱氨基作用", "kps": "", "kp": "protein_s1_3"}]}, {"i": 2, "name": "模块三：NH3转运与尿素循环", "slides": [{"i": 0, "sec": "蛋白质代谢", "title": "葡萄糖-丙氨酸循环 (p29)", "notes": "肌肉-肝脏代谢协作：肌肉丙酮酸+NH3→Ala(ALT)→血液→肝脏。\u000b肝ALT→丙酮酸+Glu→Glu脱氢酶→NH3(尿素)。\u000b丙酮酸→糖异生→葡萄糖→肌肉。\u000b一举三得：运NH3+运丙酮酸+回收碳。", "page": 29, "level": "掌握", "img": "assets/img/protein/p029.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "蛋白质代谢", "title": "尿素循环概述 (p30)", "notes": "鸟氨酸循环(Krebs 1932)分三阶段：I.Orn→Cit(线粒体)；\u000bII.Cit→Arg(细胞质)；\u000bIII.Arg→尿素+Orn(细胞质)。\u000bOrn循环再生——总量不变。\u000bI在线粒体，II/III在细胞质。", "page": 30, "level": "掌握", "img": "assets/img/protein/p030.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "蛋白质代谢", "title": "尿素循环-第I阶段 (p31)", "notes": "线粒体：①CPS-I(限速酶)：NH3+CO2+2ATP→氨甲酰磷酸+2ADP+Pi(需Mg2+和NAG别构激活)。\u000b②OTC：氨甲酰磷酸+Orn→Cit+Pi。\u000bCit运出线粒体。\u000bCPS-I是氨解毒守门酶。", "page": 31, "level": "掌握", "img": "assets/img/protein/p031.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "蛋白质代谢", "title": "尿素循环-第II阶段 (p32)", "notes": "细胞质：③ASS：Cit+Asp+ATP→精氨琥珀酸+AMP+PPi(消耗2个高能键)。\u000b④ASL：精氨琥珀酸→Arg+延胡索酸。\u000bAsp提供第2个N原子。\u000b延胡索酸→TCA。", "page": 32, "level": "掌握", "img": "assets/img/protein/p032.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "蛋白质代谢", "title": "尿素循环-第III阶段 (p33)", "notes": "细胞质：⑤精氨酸酶：Arg+H2O→尿素+Orn。\u000bOrn回线粒体→再循环。\u000b精氨酸酶仅存于肝脏——肝是唯一合成尿素的器官。\u000b这是唯一产生尿素的一步。", "page": 33, "level": "掌握", "img": "assets/img/protein/p033.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "蛋白质代谢", "title": "尿素循环总反应 (p34)", "notes": "总反应式：NH3+CO2+3ATP+2H2O+Asp→尿素+2ADP+Pi+AMP+PPi+延胡索酸。\u000b每分子尿素：消耗4个高能磷酸键；\u000b消除2分子氨基氮(1来自NH3+1来自Asp)；\u000b产1分子延胡索酸(→TCA)。", "page": 34, "level": "掌握", "img": "assets/img/protein/p034.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "蛋白质代谢", "title": "尿素循环全景图 (p35)", "notes": "尿素循环与TCA/糖异生连接全景：延胡索酸→苹果酸→OAA→Asp→回到尿素循环。\u000b苹果酸→OAA连接TCA和糖异生。\u000b尿素循环通过Asp和延胡索酸与碳代谢紧密相连。", "page": 35, "level": "理解", "img": "assets/img/protein/p035.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "蛋白质代谢", "title": "尿素循环生理意义 (p36)", "notes": "①解除氨毒——NH3剧毒必须转化；\u000b②减少CO2酸性——消耗CO2和NH3；\u000b③Orn/Cit/Arg循环使用总量不变；\u000b④线粒体+细胞质分区进行——保护细胞。\u000b肝脏是尿素合成唯一场所。", "page": 36, "level": "理解", "img": "assets/img/protein/p036.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "蛋白质代谢", "title": "酰胺形成-合成 (p37)", "notes": "动物：Glu+NH3+ATP→Gln+ADP+Pi(Gln合成酶)。\u000b植物：Asp+NH3+ATP→Asn+AMP+PPi(Asn合成酶)。\u000bGln和Asn是中性无毒分子——氨的贮存和转运形式。\u000bGln合成酶在脑组织中尤为重要。", "page": 37, "level": "理解", "img": "assets/img/protein/p037.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 9, "sec": "蛋白质代谢", "title": "酰胺水解 (p38)", "notes": "Gln+H2O→Glu+NH3(Gln酶)；\u000bAsn+H2O→Asp+NH3(Asn酶)。\u000b肝Gln酶→NH3→尿素；\u000b肾Gln酶→NH3→尿中排H+(调酸碱)；\u000b植物Asn酶→NH3供aa合成。", "page": 38, "level": "了解", "img": "assets/img/protein/p038.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "蛋白质代谢", "title": "Gln的代谢去向 (p39)", "notes": "Gln四种去向：①肝→尿素；\u000b②肾→尿氨(调酸碱)；\u000b③合成新蛋白(Gln→Glu→其他aa)；\u000b④核酸代谢(嘌呤C3/C9,嘧啶C3)。\u000bGln是体内氮代谢的枢纽分子。", "page": 39, "level": "理解", "img": "assets/img/protein/p039.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "蛋白质代谢", "title": "α-酮酸去路-还原氨基化 (p40)", "notes": "α-酮酸第一条去路：再合成aa。\u000bα-KG+NH3→Glu(Glu脱氢酶)。\u000bα-酮酸+α-KG→α-AA+Glu(转氨酶)。\u000b植物/微生物：α-KG+Gln→Glu(GOGAT)。\u000b非必需aa合成的主要方式。", "page": 40, "level": "理解", "img": "assets/img/protein/p040.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "蛋白质代谢", "title": "α-酮酸去路-生糖氨基酸 (p41)", "notes": "生糖氨基酸(13种)：碳骨架→丙酮酸/OAA/α-KG/琥珀酰CoA/延胡索酸→TCA→糖异生→葡萄糖。\u000b具体：Ala/Gly/Ser/Cys→丙酮酸；\u000bGlu/Gln/Pro/Arg/His→α-KG；\u000bMet/Val→琥珀酰CoA；\u000bAsp/Asn→OAA。", "page": 41, "level": "掌握", "img": "assets/img/protein/p041.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "蛋白质代谢", "title": "生酮和生糖生酮氨基酸 (p42)", "notes": "纯生酮(2)：Leu→乙酰CoA+乙酰乙酸；\u000bLys→乙酰乙酰CoA。\u000b完全不能→糖。\u000b生糖兼生酮(5)：Phe/Tyr→延胡索酸+乙酰乙酸；\u000bTrp→Ala+乙酰CoA；\u000bIle→琥珀酰CoA+乙酰CoA；\u000bThr→丙酮酸+乙酰CoA。", "page": 42, "level": "掌握", "img": "assets/img/protein/p042.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "protein_mcq_21", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【了解】PKU新生儿筛查的原理？", "o": ["A. CT扫描检测新生儿脑部结构异常", "B. PCR扩增PAH基因检测特定突变", "C. Guthrie试验:血Phe抑制枯草杆菌生长", "D. 尿液颜色比色法检测苯丙酮酸含量"], "a": "C", "e": "Guthrie试验:血Phe抑制枯草杆菌→抑菌圈。加拮抗剂→正常无圈(Phe低),PKU有圈(Phe高)。廉价快速。", "kp": null}, {"id": "protein_mcq_22", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】血清ALT显著升高提示什么器官损伤？", "o": ["A. 心肌损伤,AST也显著升高", "B. 骨骼肌损伤,CK-MM显著升高", "C. 肝脏损伤,ALT在肝胞浆中含量最高", "D. 肾脏损伤,Gln酶释放入血"], "a": "C", "e": "ALT(GPT)在肝细胞胞浆中含量最高→肝损伤→ALT释放入血。ALT/AST>1提示急性肝炎,<1提示酒精性肝病。", "kp": "protein_s2_0"}, {"id": "protein_mcq_23", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】精氨酸酶仅存在于哪个器官？", "o": ["A. 肾脏,合成尿素后排出体外", "B. 脑组织,参与Gln合成解氨毒", "C. 骨骼肌,参与Ala合成运NH3", "D. 肝脏,是合成尿素的唯一场所"], "a": "D", "e": "精氨酸酶(Arg+H2O→尿素+Orn)仅存在于肝脏。肝衰竭→尿素合成障碍→高氨血症→肝性脑病。", "kp": "protein_s2_4"}, {"id": "protein_mcq_24", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】磷酸吡哆醛(PLP)是哪些酶的辅酶？", "o": ["A. 仅转氨酶,催化NH2转移反应", "B. 仅Glu脱氢酶,催化氧化脱氨", "C. 转氨酶和大多数氨基酸脱羧酶", "D. 仅氨基酸脱羧酶,催化脱羧反应"], "a": "C", "e": "PLP(VB6衍生物)是转氨酶和脱羧酶的共同辅酶。PLP与酶Lys形成Schiff碱→催化NH2转移或CO2释放。VB6缺乏→aa代谢广泛受阻。", "kp": "protein_s2_2"}, {"id": "protein_mcq_25", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】胃蛋白酶原激活为胃蛋白酶需要？", "o": ["A. 胆汁酸盐的乳化作用辅助激活", "B. 肠激酶专一性切除N端肽段", "C. 胰蛋白酶水解切除抑制性肽段", "D. HCl(胃酸),提供pH≈2的酸性环境"], "a": "D", "e": "胃主细胞分泌胃蛋白酶原→胃腔被HCl激活(切除N端肽段)→活性胃蛋白酶。最适pH≈2。小肠pH升高→失活→胰蛋白酶接管。", "kp": "protein_s2_2"}, {"id": "protein_mcq_26", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】胰蛋白酶原在小肠中如何激活？", "o": ["A. 肠激酶专一性切除N端六肽→活性酶", "B. 在胃酸低pH环境中自激活", "C. HCl切除保护性肽段暴露活性中心", "D. 不需要激活,分泌即有催化活性"], "a": "A", "e": "肠激酶切除胰蛋白酶原N端六肽→暴露活性部位→激活。再级联激活糜蛋白酶原等→消化启动。", "kp": "protein_s2_2"}, {"id": "protein_mcq_27", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】哪种氨基酸脱羧产生组胺？", "o": ["A. Glu脱羧→GABA,抑制性神经递质", "B. Tyr脱羧→酪胺,升高血压", "C. Trp羟化脱羧→5-HT,调节情绪", "D. His脱羧→组胺,过敏反应介质"], "a": "D", "e": "His→组氨酸脱羧酶→组胺(不需PLP)。强力血管扩张剂+支气管收缩剂→过敏反应介质。抗组胺药阻断H1受体。", "kp": "protein_s2_12"}, {"id": "protein_mcq_28", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】26S蛋白酶体20S核心的催化活性？", "o": ["A. 仅核酸酶活性,降解核酸", "B. 仅胰蛋白酶样活性,切碱性aa后", "C. 糜蛋白酶样+胰蛋白酶样+半胱天冬酶样", "D. 仅酸性蛋白酶活性,切酸性aa后"], "a": "A", "e": "20S核心beta亚基含三种蛋白酶活性:切疏水aa(糜蛋白酶样)、切碱性aa(胰蛋白酶样)、切酸性aa(半胱天冬酶样)。协同切为3-22aa短肽。", "kp": "protein_s2_10"}, {"id": "protein_mcq_29", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【理解】肝脏为何能产酮体却不能利用酮体？", "o": ["A. 缺乏尿素酶,无法分解酮体", "B. 肝脏不产生酮体,酮体来自肌肉", "C. 缺乏琥珀酰CoA转硫酶,无法活化酮体", "D. 肝脏不含线粒体,不能氧化酮体"], "a": "C", "e": "肝脏产生酮体(HMG-CoA合成酶)但缺乏酮体利用的琥珀酰CoA转硫酶→酮体运到肝外(心/肌/肾/脑)氧化。器官分工。", "kp": "protein_s2_0"}, {"id": "protein_mcq_30", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】必需氨基酸中哪些也是生酮氨基酸？", "o": ["A. 仅Phe为生酮必需氨基酸", "B. Leu和Lys为纯生酮必需氨基酸", "C. 全部必需氨基酸均为生酮氨基酸", "D. 仅Trp为生酮必需氨基酸"], "a": "A", "e": "必需aa中:Leu和Lys是纯生酮(碳骨架不能→糖)。生糖兼生酮:Phe/Ile/Thr/Trp。纯生糖:Val/Met/His。", "kp": "protein_s2_13"}], "judge": [], "fill": [{"id": "protein_fill_2", "modI": 2, "q": "尿素循环的限速酶是________,需要________作为别构激活剂。", "a": "尿素循环的限速酶是________,需要________作为别构激活剂。", "kp": "protein_s2_2"}, {"id": "protein_fill_3", "modI": 2, "q": "骨骼肌中Glu脱氢酶活力低,主要通过________循环进行联合脱氨基。", "a": "骨骼肌中Glu脱氢酶活力低,主要通过________循环进行联合脱氨基。", "kp": "protein_s2_11"}, {"id": "protein_fill_4", "modI": 2, "q": "每合成1分子尿素消耗________个高能磷酸键,消除________分子氨基氮。", "a": "每合成1分子尿素消耗________个高能磷酸键,消除________分子氨基氮。", "kp": "protein_s2_5"}, {"id": "protein_fill_6", "modI": 2, "q": "氨在血液中主要以________形式运输,它是________性无毒分子。", "a": "氨在血液中主要以________形式运输,它是________性无毒分子。", "kp": "protein_s2_8"}, {"id": "protein_fill_8", "modI": 2, "q": "哺乳动物排氨的终产物是________,鸟类排氨的终产物是________。", "a": "哺乳动物排氨的终产物是________,鸟类排氨的终产物是________。", "kp": "protein_s2_8"}], "short": [{"id": "protein_short_2", "modI": 2, "q": "简述尿素循环的五个步骤、部位和关键酶。", "a": "简述尿素循环的五个步骤、部位和关键酶。", "kp": "protein_s2_6"}, {"id": "protein_short_6", "modI": 2, "q": "为什么肝脏能生成酮体却不能利用酮体?简述其生理意义。", "a": "为什么肝脏能生成酮体却不能利用酮体?简述其生理意义。", "kp": "protein_s2_7"}], "calc": [{"id": "protein_calc_2", "modI": 2, "q": "计算1分子精氨酸(Arg)在尿素循环中生成尿素时消耗的高能磷酸键数,以及净产能。", "a": "计算1分子精氨酸(Arg)在尿素循环中生成尿素时消耗的高能磷酸键数,以及净产能。", "steps": "计算1分子精氨酸(Arg)在尿素循环中生成尿素时消耗的高能磷酸键数,以及净产能。", "kp": "protein_s2_5"}], "term": [{"id": "protein_term_3", "modI": 2, "term": "请解释：尿素循环(鸟氨酸循环)", "def": "名词：尿素循环(鸟氨酸循环)", "kps": "", "kp": "protein_s2_1"}, {"id": "protein_term_5", "modI": 2, "term": "请解释：葡萄糖-丙氨酸循环", "def": "名词：葡萄糖-丙氨酸循环", "kps": "", "kp": "protein_s2_0"}]}, {"i": 3, "name": "模块四：氨基酸合成与代谢缺陷", "slides": [{"i": 0, "sec": "蛋白质代谢", "title": "氨基酸碳骨架代谢全景 (p43)", "notes": "20种aa碳骨架进入TCA的六入口全景图。\u000b丙酮酸入口/Ala/Gly/Ser/Cys/Thr。\u000bOAA入口/Asp/Asn。\u000bα-KG入口/Glu/Gln/Pro/Arg/His。\u000b琥珀酰CoA入口/Met/Val/Ile。\u000b延胡索酸入口/Phe/Tyr。\u000b乙酰CoA入口/Leu/Lys/部分Ile/Trp/Thr。\u000b每个入口标注对应酶。", "page": 43, "level": "掌握", "img": "assets/img/protein/p043.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "蛋白质代谢", "title": "思考题-Ala氧化 (p44)", "notes": "练习题：(1)Ala→丙酮酸→G的反应式。\u000b(2)Ala在肝脏彻底氧化产ATP数。\u000b提示：Ala→丙酮酸(ALT)→乙酰CoA(PDH,NADH)→TCA(GTP+3NADH+FADH2)。\u000bNH3→尿素(消耗4高能磷酸键)。", "page": 44, "level": "了解", "img": "assets/img/protein/p044.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "蛋白质代谢", "title": "氨基酸合成代谢 (p45)", "notes": "第三节开始：aa合成代谢。\u000b核心问题：碳骨架从哪来(EMP/TCA/PPP)？\u000bNH2从哪来(Glu转氨/还原氨基化)？\u000b非必需aa合成路径短(1-3步)，必需aa路径长(动物缺乏关键酶→进化丢失)。", "page": 45, "level": "了解", "img": "assets/img/protein/p045.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "蛋白质代谢", "title": "必需与非必需氨基酸 (p46)", "notes": "必需aa(10)：Leu/Lys/Trp/Phe/Ile/Thr/Met/Val/His/Arg——必须食物供给。\u000b非必需aa(10)：机体可合成。\u000b图中展示必需aa与生糖/生酮aa交集关系。", "page": 46, "level": "了解", "img": "assets/img/protein/p046.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "蛋白质代谢", "title": "WHO日需量 (p47)", "notes": "WHO推荐成人每日必需aa摄入量(mg/kg)：Leu39/Val26/Lys30/Ile20/Phe+Tyr25/Thr15/Met+Cys14.5/Trp4/His10。\u000b记忆口诀：甲组携一本亮色书来。\u000b条件必需aa(Arg/His)在特定条件也需外源供给。", "page": 47, "level": "了解", "img": "assets/img/protein/p047.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "蛋白质代谢", "title": "aa合成碳骨架来源 (p48)", "notes": "20种aa碳骨架6个来源：①3-P甘油酸→Ser/Gly/Cys(3)；\u000b②丙酮酸→Ala/Val/Leu(3)；\u000b③OAA→Asp/Asn/Met/Thr/Lys/Ile(6,最大)；\u000b④α-KG→Glu/Gln/Pro/Arg(4)；\u000b⑤莽草酸途径→Phe/Tyr/Trp(3)；\u000b⑥PRPP+ATP→His(1)。", "page": 48, "level": "理解", "img": "assets/img/protein/p048.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "蛋白质代谢", "title": "氨基酸合成全景图 (p49)", "notes": "从葡萄糖到20种aa的完整代谢蓝图：G→3-P甘油酸→Ser→Gly/Cys；\u000bG→丙酮酸→Ala/Val/Leu；\u000bG→PEP+E4P→莽草酸→Phe/Tyr/Trp；\u000bG→OAA→Asp家族6种；\u000bG→α-KG→Glu家族4种；\u000bPRPP→His。", "page": 49, "level": "理解", "img": "assets/img/protein/p049.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "蛋白质代谢", "title": "NH2的获得 (p50)", "notes": "-NH2三种来源：①还原氨基化(α-KG+NH3→Glu)；\u000b②转氨基作用(Glu→其他α-酮酸)；\u000b③aa间相互转化(Ser→Gly,FH4)。\u000bSer和Gly的相互转化是一碳单位代谢与aa代谢的连接点。", "page": 50, "level": "理解", "img": "assets/img/protein/p050.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "蛋白质代谢", "title": "氨基酸合成小结 (p51)", "notes": "三条总结：①碳骨架来自EMP/TCA/PPP；\u000b②碳骨架通过还原氨基化/转氨获得-NH2；\u000b③非必需aa合成短而简单，必需aa长而复杂(进化丢失)。\u000bGlu是-NH2的主要供体。", "page": 51, "level": "理解", "img": "assets/img/protein/p051.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 9, "sec": "蛋白质代谢", "title": "氨基酸代谢缺陷症 (p52)", "notes": "第四节开始：aa代谢缺陷症——大多数是特定酶缺陷→代谢中间物积累→毒性。\u000b经典两例：苯丙酮尿症(PKU,PAH缺陷)和白化病(酪氨酸酶缺陷)。\u000b均涉及芳香族aa代谢。", "page": 52, "level": "了解", "img": "assets/img/protein/p052.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "蛋白质代谢", "title": "苯丙酮尿症PKU (p53)", "notes": "PAH缺陷→Phe→Tyr受阻→Phe积累→苯丙酮酸(旁路)→尿中检出。\u000bPAH需辅酶BH4。\u000b部分PKU是BH4再生酶(DHPR)缺陷。\u000bGuthrie细菌抑制试验用于新生儿筛查。", "page": 53, "level": "了解", "img": "assets/img/protein/p053.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "蛋白质代谢", "title": "PKU症状 (p54)", "notes": "血中Phe和苯丙酮酸升高，尿中有鼠臭味。\u000b智力障碍+神经症状(忧郁/多动/孤僻)。\u000b早期诊断+低Phe饮食(特殊配方奶粉)可避免智力损伤。", "page": 54, "level": "了解", "img": "assets/img/protein/p054.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "蛋白质代谢", "title": "白化病 (p55)", "notes": "酪氨酸酶(含Cu2+)缺陷——Tyr→多巴→黑色素通路被阻断。\u000b皮肤/毛发/虹膜缺乏黑色素→白化。\u000bOCA1最常见(酪氨酸酶基因突变)。", "page": 55, "level": "了解", "img": "assets/img/protein/p055.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "蛋白质代谢", "title": "泛素-蛋白酶体途径全流程 (p14)", "notes": "①E1(泛素活化酶)消耗ATP→激活泛素C端Gly→②E2(泛素结合酶)接受活化泛素→③E3(泛素连接酶)识别靶蛋白Lys残基→泛素C端Gly与靶蛋白Lys ε-NH2形成异肽键→④多轮循环→K48多聚泛素链(≥4个泛素)→⑤26S蛋白酶体19S帽识别泛素链→⑥去折叠、去泛素→⑦20S核心三种酶活性(糜蛋白酶样/胰蛋白酶样/半胱天冬酶样)降解为3-22aa短肽→⑧去泛素化酶(DUBs)回收泛素再利用。关键:泛素化是可逆的——E1-E2-E3级联的特异性决定哪些蛋白被降解。", "page": 14, "level": "掌握", "img": "assets/img/protein/p014.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 14, "sec": "蛋白质代谢", "title": "联合脱氨基作用——两种方式 (p15)", "notes": "方式一(以Glu脱氢酶为中心,肝脏):①转氨酶收集各种aa的-NH2→α-KG→生成Glu→②Glu脱氢酶(线粒体)催化Glu+NAD(P)+→α-KG+NH3+NAD(P)H→③α-KG循环再生,NH3进入尿素循环。方式二(嘌呤核苷酸循环,骨骼肌):①aa+α-KG→α-酮酸+Glu→②Glu+OAA→α-KG+Asp(AST)→③Asp+IMP+GTP→腺苷酸代琥珀酸→④裂解→AMP+延胡索酸→⑤AMP脱氨酶→IMP+NH3。IMP循环再生。两种方式的本质:都是转氨(收集NH2)+释放NH3,只是释放NH3的酶不同。", "page": 15, "level": "掌握", "img": "assets/img/protein/p015.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 15, "sec": "蛋白质代谢", "title": "尿素循环全景——5步3阶段 (p16)", "notes": "第一阶段(线粒体):①CPS-I(限速酶,需NAG激活):NH3+CO2+2ATP→氨甲酰磷酸+2ADP+Pi→②OTC:氨甲酰磷酸+Orn→Cit+Pi。Cit运出线粒体。第二阶段(细胞质):③ASS:Cit+Asp+ATP→精氨琥珀酸+AMP+PPi(消耗~2高能键)→④ASL:精氨琥珀酸→Arg+延胡索酸(→TCA)。第三阶段(细胞质):⑤精氨酸酶:Arg+H2O→尿素+Orn。Orn回线粒体→循环。总消耗4个高能磷酸键,消除2分子NH3。Asp提供第2个N→通过延胡索酸-OAA-Asp与TCA相连。", "page": 16, "level": "掌握", "img": "assets/img/protein/p016.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 16, "sec": "蛋白质代谢", "title": "泛素-蛋白酶体——动态降解过程 (p17)", "notes": "下图动画展示了泛素-蛋白酶体途径的完整流程:靶蛋白→E1活化泛素(ATP)→E2传递→E3连接→K48多聚泛素链标记→26S蛋白酶体识别→去折叠→降解为短肽→泛素回收再利用。黄色箭头标注了每一步的酶和能量消耗。注意E3连接酶决定了底物特异性。", "page": 17, "level": "掌握", "img": "assets/img/protein/p017.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 17, "sec": "蛋白质代谢", "title": "尿素循环——5步酶促反应全景 (p18)", "notes": "下图动画逐步展示了尿素循环的5步反应:①CPS-I(限速酶)→氨甲酰磷酸→②OTC→瓜氨酸→③ASS→精氨琥珀酸→④ASL→精氨酸→⑤精氨酸酶→尿素+鸟氨酸。标注了每一步的底物、产物、酶和能量消耗。总消耗4个高能磷酸键。注意线粒体(①②)和细胞质(③④⑤)的分区进行。", "page": 18, "level": "掌握", "img": "assets/img/protein/p018.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 18, "sec": "蛋白质代谢", "title": "葡萄糖-丙氨酸循环——肌肉肝脏协作 (p19)", "notes": "下图动画展示了肌肉-肝脏之间的代谢协作:肌肉酵解→丙酮酸+NH3→Ala(ALT)→血液→肝脏→Ala→丙酮酸+Glu(ALT)→Glu脱氨→NH3(尿素循环)→丙酮酸糖异生→葡萄糖→血液→肌肉。一举三得:运NH3解毒+运丙酮酸避免乳酸堆积+回收碳骨架。", "page": 19, "level": "理解", "img": "assets/img/protein/p019.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "protein_mcq_31", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】尿素循环与TCA的连接点是什么？", "o": ["A. 柠檬酸,由乙酰CoA+OAA合成", "B. 丙酮酸,糖酵解的终产物", "C. 延胡索酸,精氨琥珀酸裂解产物入TCA", "D. 琥珀酰CoA,奇数C脂肪酸氧化产物"], "a": "D", "e": "尿素循环裂解精氨琥珀酸→延胡索酸→TCA。延胡索酸→苹果酸→OAA→AST→Asp→回尿素循环。碳氮代谢核心交叉点。", "kp": "protein_s3_15"}, {"id": "protein_mcq_32", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】GABA(γ-氨基丁酸)不足会导致？", "o": ["A. 癫痫,抑制性神经递质不足致过度兴奋", "B. 高血压,组胺过多引起血管扩张", "C. 糖尿病,胰岛素分泌不足", "D. 贫血,血红蛋白合成不足"], "a": "A", "e": "GABA(Glu脱羧产生)是CNS最重要的抑制性递质。GABA不足→神经元过度兴奋→癫痫。苯二氮卓类增强GABA受体→抗癫痫。", "kp": "protein_s3_2"}, {"id": "protein_mcq_33", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】Asn合成酶在植物中特别重要的原因？", "o": ["A. 植物不需要Asn参与氮代谢", "B. Asn是植物N贮存转运主要形式,N:C比高", "C. 植物只能合成Asn不能合成Gln", "D. Asn无特殊生理功能,仅为中间产物"], "a": "B", "e": "植物中Asn的N:C比高(2N:4C)→高效N贮存。种子萌发时Asn酶→Asp+NH3→供aa合成。木质部汁液N运输主要形式。", "kp": "protein_s3_5"}, {"id": "protein_mcq_34", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】Gln合成酶在哪个组织中最关键？", "o": ["A. 肌肉,Gln作为燃料直接氧化供能", "B. 肝脏,Gln→Glu+NH3→尿素循环", "C. 脑,Gln解氨毒,NH3不能过血脑屏障", "D. 肾脏,Gln→NH3排入尿液调节酸碱"], "a": "C", "e": "脑组织对NH3极度敏感→Gln合成酶将NH3固定为无毒Gln→运出脑→肝→尿素。肝衰竭→血NH3↑→脑Gln合成酶饱和→脑水肿。", "kp": "protein_s3_2"}, {"id": "protein_mcq_35", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】肌肉中Ala如何将NH3运到肝脏？", "o": ["A. NH3直接扩散入血,经血流至肝", "B. 经Gln运输,肝Gln酶释放NH3", "C. 丙酮酸+NH3→Ala,血运至肝,ALT逆转释NH3", "D. 经尿素形式运输至肾脏排出体外"], "a": "A", "e": "葡萄糖-丙氨酸循环:肌肉利用丙酮酸作NH3载体→Ala到肝。肝ALT→丙酮酸(→糖异生)+Glu(→脱氨→尿素)。一举多得。", "kp": "protein_s3_18"}, {"id": "protein_mcq_36", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】植物种子萌发时如何降解贮藏蛋白？", "o": ["A. 溶酶体组织蛋白酶无选择降解", "B. 种子中活性蛋白酶水解贮藏蛋白供胚生长", "C. 泛素-蛋白酶体选择性降解", "D. 胃蛋白酶和胰蛋白酶消化"], "a": "B", "e": "植物种子/幼芽/幼苗/叶和果实中含活性蛋白酶。种子萌发时水解贮藏蛋白→氨基酸→供胚生长。豆科种子含丰富蛋白酶抑制剂(生食不易消化)。", "kp": "protein_s3_16"}, {"id": "protein_mcq_37", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】微生物如何吸收利用外源蛋白质？", "o": ["A. 直接吞入蛋白质颗粒", "B. 分泌蛋白酶至培养基→水解为aa→再吸收", "C. 经泛素化标记后吸收", "D. 通过胞饮作用摄取"], "a": "B", "e": "如枯草杆菌:分泌蛋白酶至培养基→水解蛋白质为氨基酸→再吸收入体内。这是微生物获取氮源的主要方式。", "kp": "protein_s3_13"}, {"id": "protein_mcq_38", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】氨基酸脱羧产生的胺类在体内的最终去向？", "o": ["A. 直接排出体外不代谢", "B. 胺氧化酶→醛→酸→排出或进一步代谢", "C. 用于合成新蛋白质", "D. 进入TCA循环氧化供能"], "a": "B", "e": "胺类由胺氧化酶(Cu2+)催化→醛(RCHO)→酸(RCOOH)→排出或进一步代谢。胺氧化酶存在于线粒体外膜。", "kp": "protein_s3_2"}, {"id": "protein_mcq_39", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】为什么水生动物可以直接排NH3而陆生动物不行？", "o": ["A. NH3在水中溶解度低", "B. NH3可经鳃直接扩散入水,陆生需转化为尿素/尿酸节约水", "C. 水生动物不产NH3", "D. 陆生动物NH3产量更大"], "a": "B", "e": "排氨方式反映进化适应:水生→NH3(直接扩散);鸟类/爬行→尿酸(半固态省水);哺乳类→尿素(可溶需少量水)。", "kp": "protein_s3_7"}, {"id": "protein_mcq_40", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】Asn酶和Gln酶在体内分布有何不同？", "o": ["A. 都仅在肝脏表达", "B. Gln酶广泛(肝/肾),Asn酶主要在植物", "C. 都仅在肾脏表达", "D. Asn酶广泛,Gln酶仅肝脏"], "a": "B", "e": "Gln酶:肝→NH3→尿素;肾→NH3→尿中排H+调酸碱。Asn酶:植物萌发种子活跃→Asp+NH3→供aa合成。", "kp": "protein_s3_0"}, {"id": "protein_mcq_41", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】alpha-酮戊二酸如何通过还原氨基化生成Glu？", "o": ["A. α-KG+NH3→Glu,需Glu脱氢酶和NAD(P)H", "B. α-KG+Gln→Glu,需GOGAT", "C. α-KG+Ala→Glu,需ALT", "D. α-KG自发结合NH3"], "a": "A", "e": "Glu脱氢酶催化:α-KG+NH3+NAD(P)H+H+→Glu+NAD(P)++H2O。植物/微生物中还有GOGAT途径:α-KG+Gln+NADPH→2Glu+NADP+。", "kp": "protein_s3_8"}, {"id": "protein_mcq_42", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】Ala在肝脏彻底氧化净产多少ATP？(提示:NH3需进尿素循环)", "o": ["A. 约20 ATP", "B. 约12.5 ATP(氧化产12.5-尿素消耗≈4=净8.5)", "C. 约30 ATP", "D. 约5 ATP"], "a": "B", "e": "Ala→丙酮酸(ALT)→乙酰CoA(PDH,2.5 ATP NADH)→TCA(10 ATP)=12.5 ATP。NH3→尿素消耗4个高能键。净产约8.5 ATP。", "kp": "protein_s3_1"}, {"id": "protein_mcq_43", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】非必需氨基酸的碳骨架来源不包括？", "o": ["A. EMP途径的3-P甘油酸和丙酮酸", "B. TCA循环的OAA和α-KG", "C. 磷酸戊糖途径的4-P-赤藓糖", "D. 脂肪酸beta-氧化的乙酰CoA"], "a": "D", "e": "aa碳骨架来自糖代谢:EMP(3-P甘油酸→Ser/Gly/Cys;丙酮酸→Ala/Val/Leu);TCA(OAA→Asp家族;α-KG→Glu家族);PPP(E4P→莽草酸→芳香族aa)。脂肪酸乙酰CoA不能→aa(动物)。", "kp": "protein_s3_3"}, {"id": "protein_mcq_44", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】WHO推荐的成人每日Leu需要量(mg/kg体重)？", "o": ["A. 约10 mg/kg", "B. 约39 mg/kg(必需aa中最高)", "C. 约4 mg/kg", "D. 约15 mg/kg"], "a": "B", "e": "Leu 39(最高)>Lys 30>Val 26>Ile 20>Phe+Tyr 25>Thr 15>Met+Cys 14.5>His 10>Trp 4(最低)。Leu是需求量最大的必需aa,反映其在蛋白质中的丰度。", "kp": "protein_s3_4"}, {"id": "protein_mcq_45", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】Ser如何转变为Gly？需要什么辅酶？", "o": ["A. Ser→Gly,需PLP", "B. Ser+FH4→Gly+N5,N10-CH2-FH4,需Ser转羟甲基酶(PLP)", "C. Ser自发水解", "D. Ser→Gly,需ATP"], "a": "B", "e": "Ser转羟甲基酶(PLP辅酶):Ser+THF→Gly+N5,N10-亚甲基-THF+H2O。这是一碳单位代谢与aa代谢的连接点。Gly也可+亚甲基-THF→Ser(可逆)。", "kp": "protein_s3_0"}, {"id": "protein_mcq_46", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】为什么动物不能合成必需氨基酸？", "o": ["A. 缺乏碳骨架来源", "B. 合成路径长,进化中丢失了关键酶", "C. 必需aa结构太复杂", "D. 动物不需要这些aa"], "a": "B", "e": "非必需aa合成路径短(1-3步),动物保留完整酶系。必需aa合成路径长(5-10步),动物在进化中丢失了其中某些关键酶→必须从食物获取。体现了进化经济原则。", "kp": "protein_s3_3"}, {"id": "protein_mcq_47", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】氨基酸代谢缺陷症的共同特点？", "o": ["A. 都是获得性疾病", "B. 多为特定酶缺陷→代谢中间物积累→毒性效应", "C. 都是膳食缺乏引起", "D. 都是线粒体功能异常"], "a": "B", "e": "大多数aa代谢缺陷症是遗传性酶缺陷:PKU(PAH缺陷)、白化病(酪氨酸酶缺陷)、枫糖尿病(支链α-酮酸脱氢酶缺陷)等。中间物积累→旁路代谢→毒性产物→临床症状。", "kp": "protein_s3_9"}, {"id": "protein_mcq_48", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】尿素循环产生的延胡索酸如何回到循环？", "o": ["A. 直接回到尿素循环", "B. 延胡索酸→苹果酸→OAA→AST→Asp→回尿素循环", "C. 进入糖异生不再循环", "D. 氧化为CO2排出"], "a": "B", "e": "延胡索酸→延胡索酸酶→苹果酸→苹果酸脱氢酶→OAA→AST+Glu→Asp+α-KG。Asp回到尿素循环(ASS底物)。这是尿素循环与TCA/糖异生的连接枢纽。", "kp": "protein_s3_15"}, {"id": "protein_mcq_49", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】Gln的酰胺N参与哪些重要生物合成？", "o": ["A. 仅参与尿素合成", "B. 嘌呤环(C3,C9)和嘧啶环(C3)的N源", "C. 仅参与蛋白质合成", "D. 仅参与神经递质合成"], "a": "B", "e": "Gln酰胺N是嘌呤从头合成(C3来自Gln,C9来自Gln)和嘧啶合成(C3来自Gln)的必需氮源。也参与NAD+合成、氨基糖合成等。Gln是氮代谢的枢纽分子。", "kp": "protein_s3_2"}, {"id": "protein_mcq_50", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】生糖氨基酸碳骨架进入TCA的入口有哪些？", "o": ["A. 仅丙酮酸一个入口", "B. 丙酮酸/OAA/α-KG/琥珀酰CoA/延胡索酸五个入口", "C. 仅乙酰CoA入口", "D. 仅柠檬酸入口"], "a": "B", "e": "五个入口:丙酮酸(Ala/Gly/Ser/Cys/Thr);OAA(Asp/Asn);α-KG(Glu/Gln/Pro/Arg/His);琥珀酰CoA(Met/Val/Ile部分);延胡索酸(Phe/Tyr)。记住5个TCA中间物对应不同aa家族。", "kp": "protein_s3_0"}], "judge": [], "fill": [{"id": "protein_fill_7", "modI": 3, "q": "苯丙酮尿症(PKU)的缺陷酶是________,其辅酶是________。", "a": "苯丙酮尿症(PKU)的缺陷酶是________,其辅酶是________。", "kp": "protein_s3_10"}], "short": [{"id": "protein_short_3", "modI": 3, "q": "比较脂肪酸β-氧化与脂肪酸合成的异同。", "a": "比较脂肪酸β-氧化与脂肪酸合成的异同。", "kp": "protein_s3_2"}], "calc": [{"id": "protein_calc_1", "modI": 3, "q": "计算1分子丙氨酸(Ala)在肝脏中彻底氧化为CO2和H2O净产生多少ATP？(提示:NH3需进入尿素循环,尿素循环消耗4个高能磷酸键)", "a": "计算1分子丙氨酸(Ala)在肝脏中彻底氧化为CO2和H2O净产生多少ATP？(提示:NH3需进入尿素循环,尿素循环消耗4个高能磷酸键)", "steps": "计算1分子丙氨酸(Ala)在肝脏中彻底氧化为CO2和H2O净产生多少ATP？(提示:NH3需进入尿素循环,尿素循环消耗4个高能磷酸键)", "kp": "protein_s3_1"}], "term": [{"id": "protein_term_7", "modI": 3, "term": "请解释：生糖氨基酸", "def": "名词：生糖氨基酸", "kps": "", "kp": "protein_s3_2"}, {"id": "protein_term_8", "modI": 3, "term": "请解释：生酮氨基酸", "def": "名词：生酮氨基酸", "kps": "", "kp": "protein_s3_2"}, {"id": "protein_term_9", "modI": 3, "term": "请解释：必需氨基酸", "def": "名词：必需氨基酸", "kps": "", "kp": "protein_s3_3"}, {"id": "protein_term_10", "modI": 3, "term": "请解释：脱羧基作用", "def": "名词：脱羧基作用", "kps": "", "kp": "protein_s3_14"}, {"id": "protein_term_11", "modI": 3, "term": "请解释：苯丙酮尿症(PKU)", "def": "名词：苯丙酮尿症(PKU)", "kps": "", "kp": "protein_s3_10"}]}], "mcq": [{"id": "protein_mcq_1", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】泛素-蛋白酶体途径中E1/E2/E3的功能？", "o": ["A. E1活化泛素,E2传递,E3连接靶蛋白", "B. E1/E2/E3均为蛋白酶体催化亚基", "C. E1降解蛋白,E2标记,E3激活泛素", "D. E1连接靶蛋白,E2传递,E3活化泛素"], "a": "A", "e": "E1(泛素活化酶,消耗ATP)→E2(泛素结合酶)→E3(泛素连接酶)识别靶蛋白→泛素C端Gly与靶蛋白Lys ε-NH2形成异肽键。", "kp": "protein_s0_9"}, {"id": "protein_mcq_2", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】ALT/GPT催化的反应？", "o": ["A. Asp+α-KG↔OAA+Glu,需PLP为辅酶", "B. Ala+α-KG↔丙酮酸+Glu,肝脏活力最高", "C. Glu+NAD+→α-KG+NH3,线粒体酶", "D. Ala+OAA↔丙酮酸+Asp,胞质酶"], "a": "D", "e": "ALT(谷丙转氨酶):Ala+α-KG→丙酮酸+Glu(肝脏活力最高)。AST(谷草转氨酶):Asp+α-KG→OAA+Glu。辅酶都是PLP(VB6)。", "kp": null}, {"id": "protein_mcq_3", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】Glu脱氢酶的特征？", "o": ["A. 线粒体酶,脱氨活力最强,受ATP/GTP抑制", "B. 胞质酶,以FAD为辅基,氧化脱氨", "C. 仅存于肝脏,不需辅酶,直接脱氨", "D. 内质网酶,以NAD+为辅酶,还原氨化"], "a": "A", "e": "Glu脱氢酶是线粒体酶,催化Glu+NAD(P)++H2O→α-KG+NH3+NAD(P)H。ATP/GTP/NADH抑制;ADP/NAD+激活。", "kp": "protein_s0_3"}, {"id": "protein_mcq_4", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【理解】嘌呤核苷酸循环主要存在于哪个组织？", "o": ["A. 肝脏,以Glu脱氢酶为中心联合脱氨", "B. 脑组织,以Gln合成酶为主解氨毒", "C. 骨骼肌,Glu脱氢酶活力低需此途径", "D. 肾脏,以Gln酶释放NH3调节酸碱"], "a": "D", "e": "骨骼肌Glu脱氢酶活力低→以嘌呤核苷酸循环为主要脱氨方式。涉及Asp/IMP/腺苷酸代琥珀酸/AMP/腺苷酸脱氨酶。", "kp": "protein_s0_5"}, {"id": "protein_mcq_5", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】转氨酶的辅酶是？", "o": ["A. 磷酸吡哆醛(PLP),VB6衍生物", "B. 黄素腺嘌呤二核苷酸(FAD)", "C. 烟酰胺腺嘌呤二核苷酸(NAD+)", "D. 焦磷酸硫胺素(TPP),VB1衍生物"], "a": "A", "e": "PLP(磷酸吡哆醛)是所有转氨酶的辅酶(VB6衍生物)。PLP与酶Lys形成Schiff碱→转移NH2给α-酮酸。", "kp": "protein_s0_3"}, {"id": "protein_mcq_6", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】尿素循环的限速酶是？", "o": ["A. 精氨酸酶,水解精氨酸产生尿素", "B. 氨甲酰磷酸合成酶I(CPS-I),需NAG激活", "C. 鸟氨酸转氨甲酰酶(OTC),线粒体酶", "D. 精氨琥珀酸合成酶(ASS),细胞质酶"], "a": "D", "e": "CPS-I:NH3+CO2+2ATP→氨甲酰磷酸+2ADP+Pi。需Mg2+和N-乙酰谷氨酸(NAG)别构激活。是尿素循环限速步骤。", "kp": "protein_s0_12"}, {"id": "protein_mcq_7", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】每合成1分子尿素消耗几个高能磷酸键？", "o": ["A. 2个,来自2ATP→2ADP+2Pi", "B. 4个,2ATP+1ATP→AMP+PPi≈4个高能键", "C. 3个,来自3ATP→3ADP+3Pi", "D. 1个,来自1ATP→ADP+Pi"], "a": "A", "e": "2ATP(氨甲酰磷酸合成→2ADP)+1ATP→AMP+PPi(精氨琥珀酸合成,≈2个高能键)=4个高能磷酸键。", "kp": "protein_s0_0"}, {"id": "protein_mcq_8", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】尿素的两个氮原子分别来自？", "o": ["A. NH3(氨甲酰磷酸)和Asp(精氨琥珀酸)", "B. 均来自游离NH3,经CPS-I催化", "C. Gln的酰胺N和游离NH3", "D. 尿酸分解产生的N和NH3"], "a": "A", "e": "第1个N:NH3+HCO3-→氨甲酰磷酸(CPS-I)。第2个N:Asp+瓜氨酸→精氨琥珀酸(ASS)。CPS-I在线粒体,ASS在细胞质。", "kp": "protein_s0_12"}, {"id": "protein_mcq_9", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】氨在血液中主要运输形式是？", "o": ["A. 尿素,由肝脏合成后经血液运至肾", "B. 尿酸,嘌呤代谢终产物,溶解度低", "C. 谷氨酰胺(Gln),中性无毒自由过膜", "D. NH4Cl,以离子形式随血液运输"], "a": "C", "e": "Gln是中性无毒分子→Gln合成酶:Glu+NH3+ATP→Gln+ADP+Pi。脑组织依赖Gln合成酶解氨毒。肝Gln酶→Glu+NH3→尿素。", "kp": "protein_s0_1"}, {"id": "protein_mcq_10", "mod": "模块一：蛋白质的降解", "modI": 0, "q": "【掌握】葡萄糖-丙氨酸循环的意义？", "o": ["A. 仅将血液葡萄糖运至肌肉供能", "B. 运NH3(Ala至肝)+回收碳骨架(糖异生)", "C. 仅将丙氨酸运至肝脏降解供能", "D. 运输乳酸至肝脏进行Cori循环"], "a": "B", "e": "一举两得:运走NH3(Ala携带-NH2到肝);运走丙酮酸(避免乳酸积累)→肝糖异生→葡萄糖→肌肉。", "kp": "protein_s0_12"}, {"id": "protein_mcq_11", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】以下哪个是纯生酮氨基酸？", "o": ["A. Ala,碳骨架→丙酮酸,可糖异生", "B. Glu,碳骨架→α-KG,进入TCA", "C. Leu,碳骨架→乙酰CoA+乙酰乙酸", "D. Phe,碳骨架→延胡索酸+乙酰乙酸"], "a": "D", "e": "纯生酮只有Leu和Lys。Leu→乙酰CoA+乙酰乙酸;Lys→乙酰乙酰CoA。Phe/Tyr/Trp/Ile/Thr是生糖兼生酮。", "kp": "protein_s1_0"}, {"id": "protein_mcq_12", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】脱羧基作用产物GABA由哪个氨基酸生成？", "o": ["A. Asp脱羧→β-丙氨酸,泛酸前体", "B. His脱羧→组胺,过敏反应介质", "C. Tyr脱羧→酪胺,升高血压", "D. Glu脱羧→γ-氨基丁酸,抑制性递质"], "a": "D", "e": "Glu脱羧酶(GAD,PLP辅酶)→GABA。GABA是CNS最重要的抑制性神经递质。GAD仅存在于GABA能神经元中。", "kp": "protein_s1_11"}, {"id": "protein_mcq_13", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【了解】苯丙酮尿症(PKU)缺陷酶？", "o": ["A. 酪氨酸酶,催化Tyr→多巴→黑色素", "B. 苯丙氨酸羟化酶(PAH),Phe→Tyr受阻", "C. 转氨酶,催化Phe→苯丙酮酸", "D. 脱羧酶,催化Phe→苯乙胺"], "a": "A", "e": "PAH缺陷→Phe→Tyr受阻→Phe积累→苯丙酮酸(尿中检出)→智力障碍。新生儿筛查→低Phe饮食。", "kp": "protein_s1_2"}, {"id": "protein_mcq_14", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】多聚泛素化K48和K63的功能区别？", "o": ["A. 两者功能完全相同,均标记降解", "B. K48链→蛋白降解;K63链→信号转导", "C. K48链→DNA修复;K63链→蛋白降解", "D. 两者均无特定生物学功能"], "a": "C", "e": "K48连接链(>=4个泛素)→26S蛋白酶体识别→降解。K63连接链→信号转导(NF-κB)/DNA修复/内吞。", "kp": null}, {"id": "protein_mcq_15", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【了解】白化病的缺陷酶？", "o": ["A. 苯丙氨酸羟化酶(PAH),Phe→Tyr", "B. 转氨酶(ALT/AST),催化转氨反应", "C. 脱羧酶(PLP辅酶),催化脱羧反应", "D. 酪氨酸酶(含Cu2+),Tyr→多巴→黑色素"], "a": "D", "e": "酪氨酸酶(含Cu2+)→Tyr→多巴→多巴醌→黑色素。酶缺陷→无黑色素→白化。OCA1最常见。", "kp": null}, {"id": "protein_mcq_16", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】联合脱氨基的α-KG作用？", "o": ["A. 作为底物被不可逆消耗掉", "B. 循环使用:接受NH2→Glu→脱氨再生", "C. 直接释放NH3排入血液", "D. 储存NH3形成谷氨酰胺(Gln)"], "a": "A", "e": "α-KG在联合脱氨中循环:转氨酶→接受aa的NH2→Glu;Glu脱氢酶→脱氨→再生α-KG+NH3。NH2的搬运工。", "kp": "protein_s1_5"}, {"id": "protein_mcq_17", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】泛素C端Gly与靶蛋白形成什么键？", "o": ["A. 靶蛋白Glu的γ-COOH形成酯键", "B. 靶蛋白Lys的ε-NH2形成异肽键", "C. 靶蛋白Ser的-OH形成醚键", "D. 靶蛋白Cys的-SH形成硫酯键"], "a": "B", "e": "泛素C末端Gly76的α-COOH与靶蛋白Lys残基的ε-NH2形成异肽键——泛素化修饰的标志性化学键。", "kp": "protein_s1_4"}, {"id": "protein_mcq_18", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】酶原激活的生物学意义？", "o": ["A. 加快酶促反应速率,提高催化效率", "B. 防止消化酶在合成部位水解自身组织", "C. 无特殊生物学意义,是进化残留", "D. 改变酶的底物专一性和最适pH"], "a": "B", "e": "胃蛋白酶原→胃蛋白酶需HCl;胰蛋白酶原→胰蛋白酶需肠激酶。酶原形式=空间隔离+需激活=自我保护。", "kp": "protein_s1_4"}, {"id": "protein_mcq_19", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【掌握】氨甲酰磷酸合成酶I(CPS-I)的别构激活剂是？", "o": ["A. 柠檬酸,来自TCA循环的中间物", "B. ATP,提供磷酸基团和反应能量", "C. NAG(N-乙酰谷氨酸),由Arg激活合成", "D. GTP,提供别构调节所需的能量"], "a": "D", "e": "CPS-I是尿素循环限速酶,需NAG别构激活。NAG由NAG合酶以乙酰CoA+Glu合成——Arg激活NAG合酶。", "kp": "protein_s1_0"}, {"id": "protein_mcq_20", "mod": "模块二：氨基酸脱氨基", "modI": 1, "q": "【理解】生糖氨基酸与生酮氨基酸的根本区别？", "o": ["A. 碳原子数量不同,糖aa碳数更少", "B. 碳骨架能否转化为TCA中间物(能=生糖)", "C. 分子量大小不同,生糖aa分子更小", "D. 含氮量高低不同,生酮aa含氮更多"], "a": "A", "e": "生糖aa碳骨架→丙酮酸/OAA/α-KG等→TCA→糖异生→葡萄糖。生酮aa碳骨架→乙酰CoA→不能→糖(丙酮酸脱氢酶不可逆)。", "kp": "protein_s1_0"}, {"id": "protein_mcq_21", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【了解】PKU新生儿筛查的原理？", "o": ["A. CT扫描检测新生儿脑部结构异常", "B. PCR扩增PAH基因检测特定突变", "C. Guthrie试验:血Phe抑制枯草杆菌生长", "D. 尿液颜色比色法检测苯丙酮酸含量"], "a": "C", "e": "Guthrie试验:血Phe抑制枯草杆菌→抑菌圈。加拮抗剂→正常无圈(Phe低),PKU有圈(Phe高)。廉价快速。", "kp": null}, {"id": "protein_mcq_22", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】血清ALT显著升高提示什么器官损伤？", "o": ["A. 心肌损伤,AST也显著升高", "B. 骨骼肌损伤,CK-MM显著升高", "C. 肝脏损伤,ALT在肝胞浆中含量最高", "D. 肾脏损伤,Gln酶释放入血"], "a": "C", "e": "ALT(GPT)在肝细胞胞浆中含量最高→肝损伤→ALT释放入血。ALT/AST>1提示急性肝炎,<1提示酒精性肝病。", "kp": "protein_s2_0"}, {"id": "protein_mcq_23", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】精氨酸酶仅存在于哪个器官？", "o": ["A. 肾脏,合成尿素后排出体外", "B. 脑组织,参与Gln合成解氨毒", "C. 骨骼肌,参与Ala合成运NH3", "D. 肝脏,是合成尿素的唯一场所"], "a": "D", "e": "精氨酸酶(Arg+H2O→尿素+Orn)仅存在于肝脏。肝衰竭→尿素合成障碍→高氨血症→肝性脑病。", "kp": "protein_s2_4"}, {"id": "protein_mcq_24", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】磷酸吡哆醛(PLP)是哪些酶的辅酶？", "o": ["A. 仅转氨酶,催化NH2转移反应", "B. 仅Glu脱氢酶,催化氧化脱氨", "C. 转氨酶和大多数氨基酸脱羧酶", "D. 仅氨基酸脱羧酶,催化脱羧反应"], "a": "C", "e": "PLP(VB6衍生物)是转氨酶和脱羧酶的共同辅酶。PLP与酶Lys形成Schiff碱→催化NH2转移或CO2释放。VB6缺乏→aa代谢广泛受阻。", "kp": "protein_s2_2"}, {"id": "protein_mcq_25", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】胃蛋白酶原激活为胃蛋白酶需要？", "o": ["A. 胆汁酸盐的乳化作用辅助激活", "B. 肠激酶专一性切除N端肽段", "C. 胰蛋白酶水解切除抑制性肽段", "D. HCl(胃酸),提供pH≈2的酸性环境"], "a": "D", "e": "胃主细胞分泌胃蛋白酶原→胃腔被HCl激活(切除N端肽段)→活性胃蛋白酶。最适pH≈2。小肠pH升高→失活→胰蛋白酶接管。", "kp": "protein_s2_2"}, {"id": "protein_mcq_26", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】胰蛋白酶原在小肠中如何激活？", "o": ["A. 肠激酶专一性切除N端六肽→活性酶", "B. 在胃酸低pH环境中自激活", "C. HCl切除保护性肽段暴露活性中心", "D. 不需要激活,分泌即有催化活性"], "a": "A", "e": "肠激酶切除胰蛋白酶原N端六肽→暴露活性部位→激活。再级联激活糜蛋白酶原等→消化启动。", "kp": "protein_s2_2"}, {"id": "protein_mcq_27", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】哪种氨基酸脱羧产生组胺？", "o": ["A. Glu脱羧→GABA,抑制性神经递质", "B. Tyr脱羧→酪胺,升高血压", "C. Trp羟化脱羧→5-HT,调节情绪", "D. His脱羧→组胺,过敏反应介质"], "a": "D", "e": "His→组氨酸脱羧酶→组胺(不需PLP)。强力血管扩张剂+支气管收缩剂→过敏反应介质。抗组胺药阻断H1受体。", "kp": "protein_s2_12"}, {"id": "protein_mcq_28", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】26S蛋白酶体20S核心的催化活性？", "o": ["A. 仅核酸酶活性,降解核酸", "B. 仅胰蛋白酶样活性,切碱性aa后", "C. 糜蛋白酶样+胰蛋白酶样+半胱天冬酶样", "D. 仅酸性蛋白酶活性,切酸性aa后"], "a": "A", "e": "20S核心beta亚基含三种蛋白酶活性:切疏水aa(糜蛋白酶样)、切碱性aa(胰蛋白酶样)、切酸性aa(半胱天冬酶样)。协同切为3-22aa短肽。", "kp": "protein_s2_10"}, {"id": "protein_mcq_29", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【理解】肝脏为何能产酮体却不能利用酮体？", "o": ["A. 缺乏尿素酶,无法分解酮体", "B. 肝脏不产生酮体,酮体来自肌肉", "C. 缺乏琥珀酰CoA转硫酶,无法活化酮体", "D. 肝脏不含线粒体,不能氧化酮体"], "a": "C", "e": "肝脏产生酮体(HMG-CoA合成酶)但缺乏酮体利用的琥珀酰CoA转硫酶→酮体运到肝外(心/肌/肾/脑)氧化。器官分工。", "kp": "protein_s2_0"}, {"id": "protein_mcq_30", "mod": "模块三：NH3转运与尿素循环", "modI": 2, "q": "【掌握】必需氨基酸中哪些也是生酮氨基酸？", "o": ["A. 仅Phe为生酮必需氨基酸", "B. Leu和Lys为纯生酮必需氨基酸", "C. 全部必需氨基酸均为生酮氨基酸", "D. 仅Trp为生酮必需氨基酸"], "a": "A", "e": "必需aa中:Leu和Lys是纯生酮(碳骨架不能→糖)。生糖兼生酮:Phe/Ile/Thr/Trp。纯生糖:Val/Met/His。", "kp": "protein_s2_13"}, {"id": "protein_mcq_31", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】尿素循环与TCA的连接点是什么？", "o": ["A. 柠檬酸,由乙酰CoA+OAA合成", "B. 丙酮酸,糖酵解的终产物", "C. 延胡索酸,精氨琥珀酸裂解产物入TCA", "D. 琥珀酰CoA,奇数C脂肪酸氧化产物"], "a": "D", "e": "尿素循环裂解精氨琥珀酸→延胡索酸→TCA。延胡索酸→苹果酸→OAA→AST→Asp→回尿素循环。碳氮代谢核心交叉点。", "kp": "protein_s3_15"}, {"id": "protein_mcq_32", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】GABA(γ-氨基丁酸)不足会导致？", "o": ["A. 癫痫,抑制性神经递质不足致过度兴奋", "B. 高血压,组胺过多引起血管扩张", "C. 糖尿病,胰岛素分泌不足", "D. 贫血,血红蛋白合成不足"], "a": "A", "e": "GABA(Glu脱羧产生)是CNS最重要的抑制性递质。GABA不足→神经元过度兴奋→癫痫。苯二氮卓类增强GABA受体→抗癫痫。", "kp": "protein_s3_2"}, {"id": "protein_mcq_33", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】Asn合成酶在植物中特别重要的原因？", "o": ["A. 植物不需要Asn参与氮代谢", "B. Asn是植物N贮存转运主要形式,N:C比高", "C. 植物只能合成Asn不能合成Gln", "D. Asn无特殊生理功能,仅为中间产物"], "a": "B", "e": "植物中Asn的N:C比高(2N:4C)→高效N贮存。种子萌发时Asn酶→Asp+NH3→供aa合成。木质部汁液N运输主要形式。", "kp": "protein_s3_5"}, {"id": "protein_mcq_34", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】Gln合成酶在哪个组织中最关键？", "o": ["A. 肌肉,Gln作为燃料直接氧化供能", "B. 肝脏,Gln→Glu+NH3→尿素循环", "C. 脑,Gln解氨毒,NH3不能过血脑屏障", "D. 肾脏,Gln→NH3排入尿液调节酸碱"], "a": "C", "e": "脑组织对NH3极度敏感→Gln合成酶将NH3固定为无毒Gln→运出脑→肝→尿素。肝衰竭→血NH3↑→脑Gln合成酶饱和→脑水肿。", "kp": "protein_s3_2"}, {"id": "protein_mcq_35", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】肌肉中Ala如何将NH3运到肝脏？", "o": ["A. NH3直接扩散入血,经血流至肝", "B. 经Gln运输,肝Gln酶释放NH3", "C. 丙酮酸+NH3→Ala,血运至肝,ALT逆转释NH3", "D. 经尿素形式运输至肾脏排出体外"], "a": "A", "e": "葡萄糖-丙氨酸循环:肌肉利用丙酮酸作NH3载体→Ala到肝。肝ALT→丙酮酸(→糖异生)+Glu(→脱氨→尿素)。一举多得。", "kp": "protein_s3_18"}, {"id": "protein_mcq_36", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】植物种子萌发时如何降解贮藏蛋白？", "o": ["A. 溶酶体组织蛋白酶无选择降解", "B. 种子中活性蛋白酶水解贮藏蛋白供胚生长", "C. 泛素-蛋白酶体选择性降解", "D. 胃蛋白酶和胰蛋白酶消化"], "a": "B", "e": "植物种子/幼芽/幼苗/叶和果实中含活性蛋白酶。种子萌发时水解贮藏蛋白→氨基酸→供胚生长。豆科种子含丰富蛋白酶抑制剂(生食不易消化)。", "kp": "protein_s3_16"}, {"id": "protein_mcq_37", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】微生物如何吸收利用外源蛋白质？", "o": ["A. 直接吞入蛋白质颗粒", "B. 分泌蛋白酶至培养基→水解为aa→再吸收", "C. 经泛素化标记后吸收", "D. 通过胞饮作用摄取"], "a": "B", "e": "如枯草杆菌:分泌蛋白酶至培养基→水解蛋白质为氨基酸→再吸收入体内。这是微生物获取氮源的主要方式。", "kp": "protein_s3_13"}, {"id": "protein_mcq_38", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】氨基酸脱羧产生的胺类在体内的最终去向？", "o": ["A. 直接排出体外不代谢", "B. 胺氧化酶→醛→酸→排出或进一步代谢", "C. 用于合成新蛋白质", "D. 进入TCA循环氧化供能"], "a": "B", "e": "胺类由胺氧化酶(Cu2+)催化→醛(RCHO)→酸(RCOOH)→排出或进一步代谢。胺氧化酶存在于线粒体外膜。", "kp": "protein_s3_2"}, {"id": "protein_mcq_39", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】为什么水生动物可以直接排NH3而陆生动物不行？", "o": ["A. NH3在水中溶解度低", "B. NH3可经鳃直接扩散入水,陆生需转化为尿素/尿酸节约水", "C. 水生动物不产NH3", "D. 陆生动物NH3产量更大"], "a": "B", "e": "排氨方式反映进化适应:水生→NH3(直接扩散);鸟类/爬行→尿酸(半固态省水);哺乳类→尿素(可溶需少量水)。", "kp": "protein_s3_7"}, {"id": "protein_mcq_40", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】Asn酶和Gln酶在体内分布有何不同？", "o": ["A. 都仅在肝脏表达", "B. Gln酶广泛(肝/肾),Asn酶主要在植物", "C. 都仅在肾脏表达", "D. Asn酶广泛,Gln酶仅肝脏"], "a": "B", "e": "Gln酶:肝→NH3→尿素;肾→NH3→尿中排H+调酸碱。Asn酶:植物萌发种子活跃→Asp+NH3→供aa合成。", "kp": "protein_s3_0"}, {"id": "protein_mcq_41", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】alpha-酮戊二酸如何通过还原氨基化生成Glu？", "o": ["A. α-KG+NH3→Glu,需Glu脱氢酶和NAD(P)H", "B. α-KG+Gln→Glu,需GOGAT", "C. α-KG+Ala→Glu,需ALT", "D. α-KG自发结合NH3"], "a": "A", "e": "Glu脱氢酶催化:α-KG+NH3+NAD(P)H+H+→Glu+NAD(P)++H2O。植物/微生物中还有GOGAT途径:α-KG+Gln+NADPH→2Glu+NADP+。", "kp": "protein_s3_8"}, {"id": "protein_mcq_42", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】Ala在肝脏彻底氧化净产多少ATP？(提示:NH3需进尿素循环)", "o": ["A. 约20 ATP", "B. 约12.5 ATP(氧化产12.5-尿素消耗≈4=净8.5)", "C. 约30 ATP", "D. 约5 ATP"], "a": "B", "e": "Ala→丙酮酸(ALT)→乙酰CoA(PDH,2.5 ATP NADH)→TCA(10 ATP)=12.5 ATP。NH3→尿素消耗4个高能键。净产约8.5 ATP。", "kp": "protein_s3_1"}, {"id": "protein_mcq_43", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】非必需氨基酸的碳骨架来源不包括？", "o": ["A. EMP途径的3-P甘油酸和丙酮酸", "B. TCA循环的OAA和α-KG", "C. 磷酸戊糖途径的4-P-赤藓糖", "D. 脂肪酸beta-氧化的乙酰CoA"], "a": "D", "e": "aa碳骨架来自糖代谢:EMP(3-P甘油酸→Ser/Gly/Cys;丙酮酸→Ala/Val/Leu);TCA(OAA→Asp家族;α-KG→Glu家族);PPP(E4P→莽草酸→芳香族aa)。脂肪酸乙酰CoA不能→aa(动物)。", "kp": "protein_s3_3"}, {"id": "protein_mcq_44", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】WHO推荐的成人每日Leu需要量(mg/kg体重)？", "o": ["A. 约10 mg/kg", "B. 约39 mg/kg(必需aa中最高)", "C. 约4 mg/kg", "D. 约15 mg/kg"], "a": "B", "e": "Leu 39(最高)>Lys 30>Val 26>Ile 20>Phe+Tyr 25>Thr 15>Met+Cys 14.5>His 10>Trp 4(最低)。Leu是需求量最大的必需aa,反映其在蛋白质中的丰度。", "kp": "protein_s3_4"}, {"id": "protein_mcq_45", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】Ser如何转变为Gly？需要什么辅酶？", "o": ["A. Ser→Gly,需PLP", "B. Ser+FH4→Gly+N5,N10-CH2-FH4,需Ser转羟甲基酶(PLP)", "C. Ser自发水解", "D. Ser→Gly,需ATP"], "a": "B", "e": "Ser转羟甲基酶(PLP辅酶):Ser+THF→Gly+N5,N10-亚甲基-THF+H2O。这是一碳单位代谢与aa代谢的连接点。Gly也可+亚甲基-THF→Ser(可逆)。", "kp": "protein_s3_0"}, {"id": "protein_mcq_46", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【掌握】为什么动物不能合成必需氨基酸？", "o": ["A. 缺乏碳骨架来源", "B. 合成路径长,进化中丢失了关键酶", "C. 必需aa结构太复杂", "D. 动物不需要这些aa"], "a": "B", "e": "非必需aa合成路径短(1-3步),动物保留完整酶系。必需aa合成路径长(5-10步),动物在进化中丢失了其中某些关键酶→必须从食物获取。体现了进化经济原则。", "kp": "protein_s3_3"}, {"id": "protein_mcq_47", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】氨基酸代谢缺陷症的共同特点？", "o": ["A. 都是获得性疾病", "B. 多为特定酶缺陷→代谢中间物积累→毒性效应", "C. 都是膳食缺乏引起", "D. 都是线粒体功能异常"], "a": "B", "e": "大多数aa代谢缺陷症是遗传性酶缺陷:PKU(PAH缺陷)、白化病(酪氨酸酶缺陷)、枫糖尿病(支链α-酮酸脱氢酶缺陷)等。中间物积累→旁路代谢→毒性产物→临床症状。", "kp": "protein_s3_9"}, {"id": "protein_mcq_48", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】尿素循环产生的延胡索酸如何回到循环？", "o": ["A. 直接回到尿素循环", "B. 延胡索酸→苹果酸→OAA→AST→Asp→回尿素循环", "C. 进入糖异生不再循环", "D. 氧化为CO2排出"], "a": "B", "e": "延胡索酸→延胡索酸酶→苹果酸→苹果酸脱氢酶→OAA→AST+Glu→Asp+α-KG。Asp回到尿素循环(ASS底物)。这是尿素循环与TCA/糖异生的连接枢纽。", "kp": "protein_s3_15"}, {"id": "protein_mcq_49", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【了解】Gln的酰胺N参与哪些重要生物合成？", "o": ["A. 仅参与尿素合成", "B. 嘌呤环(C3,C9)和嘧啶环(C3)的N源", "C. 仅参与蛋白质合成", "D. 仅参与神经递质合成"], "a": "B", "e": "Gln酰胺N是嘌呤从头合成(C3来自Gln,C9来自Gln)和嘧啶合成(C3来自Gln)的必需氮源。也参与NAD+合成、氨基糖合成等。Gln是氮代谢的枢纽分子。", "kp": "protein_s3_2"}, {"id": "protein_mcq_50", "mod": "模块四：氨基酸合成与代谢缺陷", "modI": 3, "q": "【理解】生糖氨基酸碳骨架进入TCA的入口有哪些？", "o": ["A. 仅丙酮酸一个入口", "B. 丙酮酸/OAA/α-KG/琥珀酰CoA/延胡索酸五个入口", "C. 仅乙酰CoA入口", "D. 仅柠檬酸入口"], "a": "B", "e": "五个入口:丙酮酸(Ala/Gly/Ser/Cys/Thr);OAA(Asp/Asn);α-KG(Glu/Gln/Pro/Arg/His);琥珀酰CoA(Met/Val/Ile部分);延胡索酸(Phe/Tyr)。记住5个TCA中间物对应不同aa家族。", "kp": "protein_s3_0"}], "judge": [], "fill": [{"id": "protein_fill_1", "modI": 0, "q": "泛素C末端Gly76的α-COOH与靶蛋白Lys残基的________形成________键,这是泛素化修饰的标志。", "a": "泛素C末端Gly76的α-COOH与靶蛋白Lys残基的________形成________键,这是泛素化修饰的标志。", "kp": "protein_s0_8"}, {"id": "protein_fill_2", "modI": 2, "q": "尿素循环的限速酶是________,需要________作为别构激活剂。", "a": "尿素循环的限速酶是________,需要________作为别构激活剂。", "kp": "protein_s2_2"}, {"id": "protein_fill_3", "modI": 2, "q": "骨骼肌中Glu脱氢酶活力低,主要通过________循环进行联合脱氨基。", "a": "骨骼肌中Glu脱氢酶活力低,主要通过________循环进行联合脱氨基。", "kp": "protein_s2_11"}, {"id": "protein_fill_4", "modI": 2, "q": "每合成1分子尿素消耗________个高能磷酸键,消除________分子氨基氮。", "a": "每合成1分子尿素消耗________个高能磷酸键,消除________分子氨基氮。", "kp": "protein_s2_5"}, {"id": "protein_fill_5", "modI": 1, "q": "转氨酶的辅酶是________,它是维生素________的衍生物。", "a": "转氨酶的辅酶是________,它是维生素________的衍生物。", "kp": "protein_s1_1"}, {"id": "protein_fill_6", "modI": 2, "q": "氨在血液中主要以________形式运输,它是________性无毒分子。", "a": "氨在血液中主要以________形式运输,它是________性无毒分子。", "kp": "protein_s2_8"}, {"id": "protein_fill_7", "modI": 3, "q": "苯丙酮尿症(PKU)的缺陷酶是________,其辅酶是________。", "a": "苯丙酮尿症(PKU)的缺陷酶是________,其辅酶是________。", "kp": "protein_s3_10"}, {"id": "protein_fill_8", "modI": 2, "q": "哺乳动物排氨的终产物是________,鸟类排氨的终产物是________。", "a": "哺乳动物排氨的终产物是________,鸟类排氨的终产物是________。", "kp": "protein_s2_8"}], "short": [{"id": "protein_short_1", "modI": 0, "q": "简述泛素-蛋白酶体途径降解蛋白质的主要步骤。", "a": "简述泛素-蛋白酶体途径降解蛋白质的主要步骤。", "kp": "protein_s0_9"}, {"id": "protein_short_2", "modI": 2, "q": "简述尿素循环的五个步骤、部位和关键酶。", "a": "简述尿素循环的五个步骤、部位和关键酶。", "kp": "protein_s2_6"}, {"id": "protein_short_3", "modI": 3, "q": "比较脂肪酸β-氧化与脂肪酸合成的异同。", "a": "比较脂肪酸β-氧化与脂肪酸合成的异同。", "kp": "protein_s3_2"}, {"id": "protein_short_4", "modI": 1, "q": "简述葡萄糖-丙氨酸循环及其生理意义。", "a": "简述葡萄糖-丙氨酸循环及其生理意义。", "kp": "protein_s1_7"}, {"id": "protein_short_5", "modI": 1, "q": "简述联合脱氨基作用的两种方式。", "a": "简述联合脱氨基作用的两种方式。", "kp": "protein_s1_5"}, {"id": "protein_short_6", "modI": 2, "q": "为什么肝脏能生成酮体却不能利用酮体?简述其生理意义。", "a": "为什么肝脏能生成酮体却不能利用酮体?简述其生理意义。", "kp": "protein_s2_7"}], "calc": [{"id": "protein_calc_1", "modI": 3, "q": "计算1分子丙氨酸(Ala)在肝脏中彻底氧化为CO2和H2O净产生多少ATP？(提示:NH3需进入尿素循环,尿素循环消耗4个高能磷酸键)", "a": "计算1分子丙氨酸(Ala)在肝脏中彻底氧化为CO2和H2O净产生多少ATP？(提示:NH3需进入尿素循环,尿素循环消耗4个高能磷酸键)", "steps": "计算1分子丙氨酸(Ala)在肝脏中彻底氧化为CO2和H2O净产生多少ATP？(提示:NH3需进入尿素循环,尿素循环消耗4个高能磷酸键)", "kp": "protein_s3_1"}, {"id": "protein_calc_2", "modI": 2, "q": "计算1分子精氨酸(Arg)在尿素循环中生成尿素时消耗的高能磷酸键数,以及净产能。", "a": "计算1分子精氨酸(Arg)在尿素循环中生成尿素时消耗的高能磷酸键数,以及净产能。", "steps": "计算1分子精氨酸(Arg)在尿素循环中生成尿素时消耗的高能磷酸键数,以及净产能。", "kp": "protein_s2_5"}, {"id": "protein_calc_3", "modI": 0, "q": "某蛋白质含100个氨基酸残基,经泛素-蛋白酶体途径降解。问:(1)形成K48多聚泛素链至少需要几个泛素分子? (2)降解过程消耗多少ATP?", "a": "某蛋白质含100个氨基酸残基,经泛素-蛋白酶体途径降解。问:(1)形成K48多聚泛素链至少需要几个泛素分子? (2)降解过程消耗多少ATP?", "steps": "某蛋白质含100个氨基酸残基,经泛素-蛋白酶体途径降解。问:(1)形成K48多聚泛素链至少需要几个泛素分子? (2)降解过程消耗多少ATP?", "kp": "protein_s0_9"}, {"id": "protein_calc_4", "modI": 1, "q": "计算1分子谷氨酸(Glu)经联合脱氨基作用后,碳骨架进入TCA彻底氧化净产ATP数(不计NH3处理)。", "a": "计算1分子谷氨酸(Glu)经联合脱氨基作用后,碳骨架进入TCA彻底氧化净产ATP数(不计NH3处理)。", "steps": "计算1分子谷氨酸(Glu)经联合脱氨基作用后,碳骨架进入TCA彻底氧化净产ATP数(不计NH3处理)。", "kp": "protein_s1_5"}], "term": [{"id": "protein_term_1", "modI": 0, "term": "请解释：泛素-蛋白酶体途径", "def": "名词：泛素-蛋白酶体途径", "kps": "", "kp": "protein_s0_9"}, {"id": "protein_term_2", "modI": 1, "term": "请解释：联合脱氨基作用", "def": "名词：联合脱氨基作用", "kps": "", "kp": "protein_s1_5"}, {"id": "protein_term_3", "modI": 2, "term": "请解释：尿素循环(鸟氨酸循环)", "def": "名词：尿素循环(鸟氨酸循环)", "kps": "", "kp": "protein_s2_1"}, {"id": "protein_term_4", "modI": 1, "term": "请解释：转氨基作用", "def": "名词：转氨基作用", "kps": "", "kp": "protein_s1_0"}, {"id": "protein_term_5", "modI": 2, "term": "请解释：葡萄糖-丙氨酸循环", "def": "名词：葡萄糖-丙氨酸循环", "kps": "", "kp": "protein_s2_0"}, {"id": "protein_term_6", "modI": 1, "term": "请解释：嘌呤核苷酸循环", "def": "名词：嘌呤核苷酸循环", "kps": "", "kp": "protein_s1_7"}, {"id": "protein_term_7", "modI": 3, "term": "请解释：生糖氨基酸", "def": "名词：生糖氨基酸", "kps": "", "kp": "protein_s3_2"}, {"id": "protein_term_8", "modI": 3, "term": "请解释：生酮氨基酸", "def": "名词：生酮氨基酸", "kps": "", "kp": "protein_s3_2"}, {"id": "protein_term_9", "modI": 3, "term": "请解释：必需氨基酸", "def": "名词：必需氨基酸", "kps": "", "kp": "protein_s3_3"}, {"id": "protein_term_10", "modI": 3, "term": "请解释：脱羧基作用", "def": "名词：脱羧基作用", "kps": "", "kp": "protein_s3_14"}, {"id": "protein_term_11", "modI": 3, "term": "请解释：苯丙酮尿症(PKU)", "def": "名词：苯丙酮尿症(PKU)", "kps": "", "kp": "protein_s3_10"}, {"id": "protein_term_12", "modI": 1, "term": "请解释：氧化脱氨基作用", "def": "名词：氧化脱氨基作用", "kps": "", "kp": "protein_s1_3"}], "preview": null, "appcards": []};